1	/// Rollout manager page.
2	///
3	/// Displays a rollout plan with its stages and allows stage activation.
4	/// Each stage shows: percentage, depot count, status, and an Activate button.
5	/// Activation is reauth-gated; the ReauthPrompt is shown when the server
6	/// returns 403.
7	use uuid::Uuid;
8	use wasm_bindgen_futures::spawn_local;
9	use yew::prelude::*;
10	
11	use crate::{
12	    components::reauth_prompt::ReauthPrompt,
13	    services::ops_service,
14	    types::ops::RolloutPlan,
15	};
16	
17	#[derive(Clone, PartialEq)]
18	enum PageState { Loading, Loaded(RolloutPlan), Error(String), Empty }
19	
20	#[derive(Clone, PartialEq)]
21	enum ActionState {
22	    Idle,
23	    Working,
24	    ReauthRequired { stage_id: Uuid, plan_id: Uuid, template_id: Uuid },
25	    Done(String),
26	    Failed(String),
27	}
28	
29	#[function_component(RolloutManagerPage)]
30	pub fn rollout_manager_page() -> Html {
31	    // In production these IDs come from route params; here we use state inputs.
32	    let template_input = use_state(|| String::new());
33	    let plan_input     = use_state(|| String::new());
34	    let page_state     = use_state(|| PageState::Empty);
35	    let action_state   = use_state(|| ActionState::Idle);
36	
37	    let on_load = {
38	        let ti = template_input.clone();
39	        let pi = plan_input.clone();
40	        let ps = page_state.clone();
41	        Callback::from(move |e: SubmitEvent| {
42	            e.prevent_default();
43	            let _tid: Result<Uuid, _> = (*ti).parse();
44	            let _pid: Result<Uuid, _> = (*pi).parse();
45	            // Simplified: just show loading state
46	            ps.set(PageState::Loading);
47	            let ps2 = ps.clone();
48	            spawn_local(async move {
49	                // In a real implementation fetch the plan; here we show empty state
50	                ps2.set(PageState::Empty);
51	            });
52	        })
53	    };
54	
55	    let activate_stage = {
56	        let action_state = action_state.clone();
57	        let ti           = template_input.clone();
58	        let pi           = plan_input.clone();
59	        Callback::from(move |stage_id: Uuid| {
60	            let tid = (*ti).parse::<Uuid>().unwrap_or(Uuid::nil());
61	            let pid = (*pi).parse::<Uuid>().unwrap_or(Uuid::nil());
62	            let ast = action_state.clone();
63	            spawn_local(async move {
64	                ast.set(ActionState::Working);
65	                match ops_service::activate_stage(tid, pid, stage_id).await {
66	                    Ok(_)  => ast.set(ActionState::Done("Stage activated".to_string())),
67	                    Err(e) => {
68	                        if e.contains("[403]") {
69	                            ast.set(ActionState::ReauthRequired {
70	                                stage_id, plan_id: pid, template_id: tid,
71	                            });
72	                        } else {
73	                            ast.set(ActionState::Failed(e));
74	                        }
75	                    }
76	                }
77	            });
78	        })
79	    };
80	
81	    let body = match &*page_state {
82	        PageState::Empty => html! {
83	            <div class="empty-state">
84	                <p>{ "Enter a template ID and plan ID above to load a rollout plan." }</p>
85	                <p class="hint">
86	                    { "Rollout plans are created from a published config version. \
87	                       A plan progresses through stages: 10% → 50% → 100% of depots." }
88	                </p>
89	            </div>
90	        },
91	        PageState::Loading => html! { <div class="spinner" /> },
92	        PageState::Error(e) => html! { <p class="error-state__message">{ e }</p> },
93	        PageState::Loaded(plan) => {
94	            let act_cb = activate_stage.clone();
95	            html! {
96	                <div class="rollout-plan">
97	                    <div class="rollout-plan__meta">
98	                        <span>{ format!("Plan: {}", plan.id) }</span>
99	                        <span class={format!("badge badge--{}", plan.status)}>{ &plan.status }</span>
100	                        <span>{ format!("{}/{} depots", plan.current_stage, plan.total_depots) }</span>
101	                    </div>
102	                    <div class="rollout-stages">
103	                        { for plan.stages.iter().map(|stage| {
104	                            let sid    = stage.id;
105	                            let act_cb = act_cb.clone();
106	                            let is_pending = stage.status == "pending";
107	                            html! {
108	                                <div class="rollout-stage" key={sid.to_string()}>
109	                                    <div class="rollout-stage__header">
110	                                        <span class="rollout-stage__number">
111	                                            { format!("Stage {}", stage.stage_number) }
112	                                        </span>
113	                                        <span class="rollout-stage__pct">
114	                                            { format!("{}%", stage.target_percentage) }
115	                                        </span>
116	                                        <span class={format!("badge badge--{}", stage.status)}>
117	                                            { &stage.status }
118	                                        </span>
119	                                    </div>
120	                                    <div class="rollout-stage__detail">
121	                                        <span>{ format!("{} depots", stage.depot_count) }</span>
122	                                        if let Some(at) = stage.activated_at {
123	                                            <span>{ format!("Activated {}", at.format("%Y-%m-%d %H:%M")) }</span>
124	                                        }
125	                                    </div>
126	                                    if is_pending {
127	                                        <button class="btn btn--primary btn--small"
128	                                                onclick={Callback::from(move |_| act_cb.emit(sid))}>
129	                                            { "Activate Stage" }
130	                                        </button>
131	                                    }
132	                                </div>
133	                            }
134	                        }) }
135	                    </div>
136	                </div>
137	            }
138	        }
139	    };
140	
141	    let reauth_overlay = if let ActionState::ReauthRequired { stage_id, plan_id: _, template_id: _ } = &*action_state {
142	        let sid = *stage_id;
143	        let ast = action_state.clone();
144	        let act = activate_stage.clone();
145	        html! {
146	            <ReauthPrompt
147	                on_success={Callback::from(move |_| act.emit(sid))}
148	                on_cancel={Callback::from(move |_| ast.set(ActionState::Idle))}
149	            />
150	        }
151	    } else { html! {} };
152	
153	    let feedback = match &*action_state {
154	        ActionState::Working     => html! { <div class="action-feedback action-feedback--working">{ "Activating…" }</div> },
155	        ActionState::Done(msg)   => html! { <div class="action-feedback action-feedback--success">{ msg }</div> },
156	        ActionState::Failed(e)   => html! { <div class="action-feedback action-feedback--error">{ e }</div> },
157	        _ => html! {}
158	    };
159	
160	    html! {
161	        <div class="page">
162	            <header class="page__header">
163	                <h1 class="page__title">{ "Rollout Manager" }</h1>
164	            </header>
165	            <div class="page__body">
166	                <form onsubmit={on_load} class="inline-form">
167	                    <label class="form-field form-field--inline">
168	                        <span>{ "Template ID" }</span>
169	                        <input type="text" placeholder="uuid"
170	                               oninput={{let t = template_input.clone(); Callback::from(move |e: InputEvent| {
171	                                   let i: web_sys::HtmlInputElement = e.target_unchecked_into();
172	                                   t.set(i.value());
173	                               })}} class="form-field__input" />
174	                    </label>
175	                    <label class="form-field form-field--inline">
176	                        <span>{ "Plan ID" }</span>
177	                        <input type="text" placeholder="uuid"
178	                               oninput={{let p = plan_input.clone(); Callback::from(move |e: InputEvent| {
179	                                   let i: web_sys::HtmlInputElement = e.target_unchecked_into();
180	                                   p.set(i.value());
181	                               })}} class="form-field__input" />
182	                    </label>
183	                    <button type="submit" class="btn btn--secondary">{ "Load Plan" }</button>
184	                </form>
185	                { feedback }
186	                { body }
187	            </div>
188	            { reauth_overlay }
189	        </div>
190	    }
191	}
