1	/// Finance: Statement import page.
2	///
3	/// Lists all imported bank/payment statements.  Finance analysts can trigger
4	/// a new import (in production, file upload would be handled as multipart;
5	/// here we use a simplified JSON payload for the demo path).
6	use wasm_bindgen_futures::spawn_local;
7	use yew::prelude::*;
8	
9	use crate::{
10	    services::finance_service,
11	    types::finance::{StatementImport, UploadStatementRequest},
12	};
13	
14	#[derive(Clone, PartialEq)]
15	enum PageState { Loading, Loaded(Vec<StatementImport>), Error(String) }
16	
17	#[derive(Clone, PartialEq)]
18	enum UploadState { Idle, Working, Done(String), Failed(String) }
19	
20	#[function_component(StatementsPage)]
21	pub fn statements_page() -> Html {
22	    let page_state   = use_state(|| PageState::Loading);
23	    let upload_state = use_state(|| UploadState::Idle);
24	    let source_input = use_state(|| "bank_csv".to_string());
25	
26	    let reload = {
27	        let ps = page_state.clone();
28	        move || {
29	            let ps = ps.clone();
30	            spawn_local(async move {
31	                match finance_service::list_statements().await {
32	                    Ok(items) => ps.set(PageState::Loaded(items)),
33	                    Err(e)    => ps.set(PageState::Error(e)),
34	                }
35	            });
36	        }
37	    };
38	
39	    { let r = reload.clone(); use_effect_with((), move |_| { r(); || () }); }
40	
41	    let on_upload = {
42	        let us     = upload_state.clone();
43	        let src    = source_input.clone();
44	        let reload = reload.clone();
45	        Callback::from(move |e: SubmitEvent| {
46	            e.prevent_default();
47	            let us2    = us.clone();
48	            let reload = reload.clone();
49	            let body = UploadStatementRequest {
50	                filename:             format!("statement_{}.csv", (*src).clone()),
51	                source:               (*src).clone(),
52	                content_base64:       String::new(), // placeholder for demo
53	                expected_fingerprint: None,
54	            };
55	            spawn_local(async move {
56	                us2.set(UploadState::Working);
57	                match finance_service::upload_statement(&body).await {
58	                    Ok(resp) => {
59	                        us2.set(UploadState::Done(format!(
60	                            "Imported {} records (valid: {})",
61	                            resp.record_count, resp.is_valid
62	                        )));
63	                        reload();
64	                    }
65	                    Err(e) => us2.set(UploadState::Failed(e)),
66	                }
67	            });
68	        })
69	    };
70	
71	    let content = match &*page_state {
72	        PageState::Loading => html! { <div class="loading-state"><div class="spinner"/></div> },
73	        PageState::Error(e) => html! { <p class="error-state__message">{ e }</p> },
74	        PageState::Loaded(items) if items.is_empty() => html! {
75	            <div class="empty-state"><p>{ "No statements imported yet." }</p></div>
76	        },
77	        PageState::Loaded(items) => html! {
78	            <table class="data-table">
79	                <thead>
80	                    <tr>
81	                        <th>{ "Filename" }</th>
82	                        <th>{ "Source" }</th>
83	                        <th>{ "Records" }</th>
84	                        <th>{ "Import Date" }</th>
85	                        <th>{ "Status" }</th>
86	                    </tr>
87	                </thead>
88	                <tbody>
89	                    { for items.iter().map(|s| html! {
90	                        <tr key={s.id.to_string()}>
91	                            <td>{ &s.filename }</td>
92	                            <td>{ &s.source }</td>
93	                            <td>{ s.total_records }</td>
94	                            <td>{ s.import_date.to_string() }</td>
95	                            <td>
96	                                <span class={format!("badge badge--{}", s.status)}>{ &s.status }</span>
97	                            </td>
98	                        </tr>
99	                    }) }
100	                </tbody>
101	            </table>
102	        },
103	    };
104	
105	    let feedback = match &*upload_state {
106	        UploadState::Working   => html! { <div class="action-feedback action-feedback--working">{ "Uploading…" }</div> },
107	        UploadState::Done(msg) => html! { <div class="action-feedback action-feedback--success">{ msg }</div> },
108	        UploadState::Failed(e) => html! { <div class="action-feedback action-feedback--error">{ e }</div> },
109	        UploadState::Idle      => html! {},
110	    };
111	
112	    html! {
113	        <div class="page">
114	            <header class="page__header">
115	                <h1 class="page__title">{ "Statement Imports" }</h1>
116	            </header>
117	            <div class="page__body">
118	                <form onsubmit={on_upload} class="inline-form">
119	                    <label class="form-field form-field--inline">
120	                        <span>{ "Source" }</span>
121	                        <select class="form-field__input"
122	                                onchange={{
123	                                    let s = source_input.clone();
124	                                    Callback::from(move |e: Event| {
125	                                        let el: web_sys::HtmlSelectElement = e.target_unchecked_into();
126	                                        s.set(el.value());
127	                                    })
128	                                }}>
129	                            <option value="bank_csv">{ "Bank CSV" }</option>
130	                            <option value="stripe">{ "Stripe" }</option>
131	                            <option value="sumup">{ "SumUp" }</option>
132	                        </select>
133	                    </label>
134	                    <button type="submit" class="btn btn--primary">{ "Import Statement" }</button>
135	                </form>
136	                { feedback }
137	                { content }
138	            </div>
139	        </div>
140	    }
141	}
