1	use actix_web::{http::StatusCode, HttpResponse, ResponseError};
2	use serde::Serialize;
3	
4	#[derive(Debug, thiserror::Error)]
5	pub enum AppError {
6	    #[error("Database error")]
7	    Database(#[from] sqlx::Error),
8	
9	    /// 401 — caller is not authenticated or token is invalid.
10	    #[error("Unauthorized: {0}")]
11	    Unauthorized(String),
12	
13	    /// 403 — caller is authenticated but lacks permission (e.g. reauth required).
14	    #[error("Forbidden: {0}")]
15	    Forbidden(String),
16	
17	    /// 400 — malformed request body or parameters.
18	    #[error("Bad request: {0}")]
19	    BadRequest(String),
20	
21	    /// 404 — requested resource does not exist.
22	    #[error("Not found: {0}")]
23	    NotFound(String),
24	
25	    /// 429 — account is locked due to too many failed attempts.
26	    #[error("Account locked until {0}")]
27	    AccountLocked(String),
28	
29	    /// 500 — unexpected server-side failure.
30	    #[error("Internal server error")]
31	    Internal(String),
32	}
33	
34	#[derive(Serialize)]
35	struct ErrorBody {
36	    error: String,
37	    code:  &'static str,
38	}
39	
40	impl AppError {
41	    fn error_code(&self) -> &'static str {
42	        match self {
43	            AppError::Database(_) | AppError::Internal(_) => "INTERNAL_ERROR",
44	            AppError::Unauthorized(_)                     => "UNAUTHORIZED",
45	            AppError::Forbidden(_)                        => "FORBIDDEN",
46	            AppError::BadRequest(_)                       => "BAD_REQUEST",
47	            AppError::NotFound(_)                         => "NOT_FOUND",
48	            AppError::AccountLocked(_)                    => "ACCOUNT_LOCKED",
49	        }
50	    }
51	}
52	
53	impl ResponseError for AppError {
54	    fn status_code(&self) -> StatusCode {
55	        match self {
56	            AppError::Database(_) | AppError::Internal(_) => StatusCode::INTERNAL_SERVER_ERROR,
57	            AppError::Unauthorized(_)                     => StatusCode::UNAUTHORIZED,
58	            AppError::Forbidden(_)                        => StatusCode::FORBIDDEN,
59	            AppError::BadRequest(_)                       => StatusCode::BAD_REQUEST,
60	            AppError::NotFound(_)                         => StatusCode::NOT_FOUND,
61	            AppError::AccountLocked(_)                    => StatusCode::TOO_MANY_REQUESTS,
62	        }
63	    }
64	
65	    fn error_response(&self) -> HttpResponse {
66	        // Log server-side errors; surface nothing to the caller.
67	        if let AppError::Database(ref e) = self {
68	            tracing::error!("Database error: {:?}", e);
69	        }
70	        if let AppError::Internal(ref msg) = self {
71	            tracing::error!("Internal error: {}", msg);
72	        }
73	        HttpResponse::build(self.status_code()).json(ErrorBody {
74	            error: self.to_string(),
75	            code:  self.error_code(),
76	        })
77	    }
78	}
79	
80	impl From<crate::crypto::CryptoError> for AppError {
81	    fn from(e: crate::crypto::CryptoError) -> Self {
82	        // Never leak crypto internals to the caller.
83	        tracing::error!("crypto error: {}", e);
84	        AppError::Internal("Cryptographic operation failed".to_string())
85	    }
86	}
87	
88	impl From<argon2::password_hash::Error> for AppError {
89	    fn from(_err: argon2::password_hash::Error) -> Self {
90	        // Never leak hash internals to caller.
91	        AppError::Internal("Password processing error".to_string())
92	    }
93	}
