1	/// Generic API client helpers.
2	///
3	/// All API calls go through `api_get`, `api_post`, `api_put`, `api_delete`
4	/// which automatically attach the Bearer token from localStorage.
5	///
6	/// Offline-first: if the fetch itself fails (network unavailable), the
7	/// functions return an `Err` with a descriptive message so components can
8	/// show an offline state rather than crashing.
9	use gloo_net::http::{Request, Response};
10	use serde::{de::DeserializeOwned, Serialize};
11	
12	use crate::store::auth_store::load_persisted_token;
13	
14	const API_BASE: &str = "";   // same origin — frontend is served by/proxied to the API
15	
16	/// Build a request with the Bearer token header if a token is available.
17	fn bearer_header() -> Option<String> {
18	    load_persisted_token().map(|t| format!("Bearer {}", t))
19	}
20	
21	fn apply_auth(req: Request) -> Request {
22	    match bearer_header() {
23	        Some(h) => req.header("Authorization", &h),
24	        None    => req,
25	    }
26	}
27	
28	pub async fn api_get<T: DeserializeOwned>(path: &str) -> Result<T, String> {
29	    let req = apply_auth(Request::get(&format!("{}{}", API_BASE, path)));
30	    let resp = req.send().await.map_err(|e| format!("Network error: {}", e))?;
31	    parse_response(resp).await
32	}
33	
34	pub async fn api_post<B: Serialize, T: DeserializeOwned>(
35	    path: &str,
36	    body: &B,
37	) -> Result<T, String> {
38	    let req = apply_auth(
39	        Request::post(&format!("{}{}", API_BASE, path))
40	            .header("Content-Type", "application/json"),
41	    );
42	    let req = req.json(body).map_err(|e| format!("Serialisation error: {}", e))?;
43	    let resp = req.send().await.map_err(|e| format!("Network error: {}", e))?;
44	    parse_response(resp).await
45	}
46	
47	pub async fn api_put<B: Serialize, T: DeserializeOwned>(
48	    path: &str,
49	    body: &B,
50	) -> Result<T, String> {
51	    let req = apply_auth(
52	        Request::put(&format!("{}{}", API_BASE, path))
53	            .header("Content-Type", "application/json"),
54	    );
55	    let req = req.json(body).map_err(|e| format!("Serialisation error: {}", e))?;
56	    let resp = req.send().await.map_err(|e| format!("Network error: {}", e))?;
57	    parse_response(resp).await
58	}
59	
60	pub async fn api_delete(path: &str) -> Result<(), String> {
61	    let req = apply_auth(Request::delete(&format!("{}{}", API_BASE, path)));
62	    let resp = req.send().await.map_err(|e| format!("Network error: {}", e))?;
63	    if resp.ok() {
64	        Ok(())
65	    } else {
66	        Err(api_error_text(resp).await)
67	    }
68	}
69	
70	pub async fn api_post_empty<T: DeserializeOwned>(path: &str) -> Result<T, String> {
71	    let req = apply_auth(
72	        Request::post(&format!("{}{}", API_BASE, path))
73	            .header("Content-Type", "application/json"),
74	    );
75	    let req = req.body("{}").map_err(|e| format!("Body error: {}", e))?;
76	    let resp = req.send().await.map_err(|e| format!("Network error: {}", e))?;
77	    parse_response(resp).await
78	}
79	
80	async fn parse_response<T: DeserializeOwned>(resp: Response) -> Result<T, String> {
81	    if resp.ok() {
82	        resp.json::<T>().await.map_err(|e| format!("Parse error: {}", e))
83	    } else {
84	        Err(api_error_text(resp).await)
85	    }
86	}
87	
88	async fn api_error_text(resp: Response) -> String {
89	    let status = resp.status();
90	    let body = resp.text().await.unwrap_or_default();
91	    // Try to extract the "error" field from a standard JSON error body
92	    if let Ok(json) = serde_json::from_str::<serde_json::Value>(&body) {
93	        if let Some(msg) = json.get("error").and_then(|v| v.as_str()) {
94	            return format!("[{}] {}", status, msg);
95	        }
96	    }
97	    format!("[{}] {}", status, body)
98	}
