                            <th>{ "Code" }</th>
                            <th>{ "Name" }</th>
                            <th>{ "Status" }</th>
                            <th>{ "Version" }</th>
                            <th>{ "Actions" }</th>
                        </tr>
                    </thead>
                    <tbody>
                        { for routes.iter().map(|r| {
