use wasm_bindgen_test::*;

wasm_bindgen_test_configure!(run_in_browser);

// ── Real type imports ─────────────────────────────────────────────────────────

use transitops_frontend::types::auth::SessionInfo;
use transitops_frontend::types::ops::{
