// ── Auth / role-guard routing using real SessionInfo ─────────────────────────

mod auth_role_guard {
    use super::*;

    fn make_session(role: &str) -> SessionInfo {
        SessionInfo {
            username:   "testuser".to_string(),
            role:       role.to_string(),
            session_id: None,
        }
    }

    #[wasm_bindgen_test]
    fn unauthenticated_should_redirect() {
