75	/// Fetch the full details of a single notification (for the detail drawer).
76	pub async fn fetch_one(id: Uuid) -> Result<Notification, gloo_net::Error> {
77	    get(&format!("{}/{}", BASE, id))
78	        .send()
79	        .await?
80	        .json::<Notification>()
81	        .await
82	}
