1	/// Channel preferences & DND management page.
2	///
3	/// Allows users to configure per-channel preferences (email, push, in-app)
4	/// and set a Do-Not-Disturb window (start/end hours in UTC).
5	use wasm_bindgen_futures::spawn_local;
6	use yew::prelude::*;
7	
8	use crate::services::api;
9	
10	#[derive(Clone, PartialEq, serde::Deserialize, serde::Serialize, Default)]
11	pub struct ChannelPreferences {
12	    pub email_enabled:  bool,
13	    pub push_enabled:   bool,
14	    pub in_app_enabled: bool,
15	    pub dnd_enabled:    bool,
16	    pub dnd_start_hour: u8,   // 0–23 UTC
17	    pub dnd_end_hour:   u8,   // 0–23 UTC
18	}
19	
20	#[derive(Clone, PartialEq)]
21	enum PageState { Loading, Loaded(ChannelPreferences), Error(String) }
22	
23	#[derive(Clone, PartialEq)]
24	enum SaveState { Idle, Working, Done, Failed(String) }
25	
26	#[function_component(PreferencesPage)]
27	pub fn preferences_page() -> Html {
28	    let page_state = use_state(|| PageState::Loading);
29	    let save_state = use_state(|| SaveState::Idle);
30	    let prefs      = use_state(ChannelPreferences::default);
31	
32	    {
33	        let ps  = page_state.clone();
34	        let prf = prefs.clone();
35	        use_effect_with((), move |_| {
36	            spawn_local(async move {
37	                match api::api_get::<ChannelPreferences>("/notifications/preferences").await {
38	                    Ok(p)  => { prf.set(p.clone()); ps.set(PageState::Loaded(p)); }
39	                    Err(e) => ps.set(PageState::Error(e)),
40	                }
41	            });
42	            || ()
43	        });
44	    }
45	
46	    let on_save = {
47	        let prefs = prefs.clone();
48	        let ss    = save_state.clone();
49	        Callback::from(move |e: SubmitEvent| {
50	            e.prevent_default();
51	            let p   = (*prefs).clone();
52	            let ss2 = ss.clone();
53	            spawn_local(async move {
54	                ss2.set(SaveState::Working);
55	                match api::api_put::<ChannelPreferences, ChannelPreferences>(
56	                    "/notifications/preferences", &p
57	                ).await {
58	                    Ok(_)  => ss2.set(SaveState::Done),
59	                    Err(e) => ss2.set(SaveState::Failed(e)),
60	                }
61	            });
62	        })
63	    };
64	
65	    let toggle = |field: &'static str| {
66	        let p = prefs.clone();
67	        Callback::from(move |_: Event| {
68	            let mut new = (*p).clone();
69	            match field {
70	                "email"  => new.email_enabled  = !new.email_enabled,
71	                "push"   => new.push_enabled   = !new.push_enabled,
72	                "in_app" => new.in_app_enabled = !new.in_app_enabled,
73	                "dnd"    => new.dnd_enabled    = !new.dnd_enabled,
74	                _ => {}
75	            }
76	            p.set(new);
77	        })
78	    };
79	
80	    let feedback = match &*save_state {
81	        SaveState::Working    => html! { <div class="action-feedback action-feedback--working">{ "Saving…" }</div> },
82	        SaveState::Done       => html! { <div class="action-feedback action-feedback--success">{ "Preferences saved." }</div> },
83	        SaveState::Failed(e)  => html! { <div class="action-feedback action-feedback--error">{ e }</div> },
84	        SaveState::Idle       => html! {},
85	    };
86	
87	    let body = match &*page_state {
88	        PageState::Loading => html! { <div class="loading-state"><div class="spinner"/></div> },
89	        PageState::Error(e) => html! { <p class="error-state__message">{ e }</p> },
90	        PageState::Loaded(_) => {
91	            let p = (*prefs).clone();
92	            html! {
93	                <form onsubmit={on_save} class="prefs-form">
94	                    <fieldset class="prefs-form__section">
95	                        <legend>{ "Channels" }</legend>
96	                        <label class="form-field form-field--row">
97	                            <input type="checkbox" checked={p.email_enabled}
98	                                   onchange={toggle("email")} />
99	                            { "Email" }
100	                        </label>
101	                        <label class="form-field form-field--row">
102	                            <input type="checkbox" checked={p.push_enabled}
103	                                   onchange={toggle("push")} />
104	                            { "Push notifications" }
105	                        </label>
106	                        <label class="form-field form-field--row">
107	                            <input type="checkbox" checked={p.in_app_enabled}
108	                                   onchange={toggle("in_app")} />
109	                            { "In-app" }
110	                        </label>
111	                    </fieldset>
112	                    <fieldset class="prefs-form__section">
113	                        <legend>{ "Do Not Disturb" }</legend>
114	                        <label class="form-field form-field--row">
115	                            <input type="checkbox" checked={p.dnd_enabled}
116	                                   onchange={toggle("dnd")} />
117	                            { "Enable DND window" }
118	                        </label>
119	                        if p.dnd_enabled {
120	                            <div class="prefs-form__dnd-hours">
121	                                <label class="form-field form-field--inline">
122	                                    <span>{ "Start hour (UTC)" }</span>
123	                                    <input type="number" min="0" max="23"
124	                                           value={p.dnd_start_hour.to_string()}
125	                                           class="form-field__input form-field__input--sm" />
126	                                </label>
127	                                <label class="form-field form-field--inline">
128	                                    <span>{ "End hour (UTC)" }</span>
129	                                    <input type="number" min="0" max="23"
130	                                           value={p.dnd_end_hour.to_string()}
131	                                           class="form-field__input form-field__input--sm" />
132	                                </label>
133	                            </div>
134	                        }
135	                    </fieldset>
136	                    <button type="submit" class="btn btn--primary">{ "Save Preferences" }</button>
137	                </form>
138	            }
139	        }
140	    };
141	
142	    html! {
143	        <div class="page">
144	            <header class="page__header">
145	                <h1 class="page__title">{ "Notification Preferences" }</h1>
146	            </header>
147	            { feedback }
148	            <div class="page__body">{ body }</div>
149	        </div>
150	    }
151	}
