1	/// Ops config version list page.
2	///
3	/// Shows all config versions for available templates.  Supports:
4	///   - Loading / empty / error states
5	///   - Publish / unpublish / schedule actions (admin only)
6	///     → triggers ReauthPrompt when server returns 403
7	///   - Link to diff view and rollout manager
8	use uuid::Uuid;
9	use wasm_bindgen_futures::spawn_local;
10	use yew::prelude::*;
11	
12	use crate::{
13	    components::reauth_prompt::ReauthPrompt,
14	    services::ops_service,
15	    types::ops::ConfigVersion,
16	};
17	
18	// ── Page state ────────────────────────────────────────────────────────────────
19	
20	#[derive(Clone, PartialEq)]
21	enum PageState {
22	    Loading,
23	    Loaded(Vec<ConfigVersion>),
24	    Error(String),
25	}
26	
27	#[derive(Clone, PartialEq)]
28	enum ActionState {
29	    Idle,
30	    Confirming { action: PendingAction, version_id: Uuid, template_id: Uuid },
31	    ReauthRequired { action: PendingAction, version_id: Uuid, template_id: Uuid },
32	    Working,
33	    Done(String),
34	    Failed(String),
35	}
36	
37	#[derive(Clone, PartialEq, Debug)]
38	enum PendingAction { Publish, Unpublish }
39	
40	// ── Component ─────────────────────────────────────────────────────────────────
41	
42	/// Hardcoded known template IDs for the common config areas.
43	/// In production these would be fetched from GET /ops/configs/templates.
44	const DEMO_TEMPLATE_ID: &str = "00000000-0000-0000-0000-000000000001";
45	
46	#[function_component(ConfigListPage)]
47	pub fn config_list_page() -> Html {
48	    // For demo purposes, use a fixed template_id; in production fetch templates first.
49	    let template_id: Uuid = DEMO_TEMPLATE_ID.parse().unwrap_or(Uuid::nil());
50	
51	    let page_state   = use_state(|| PageState::Loading);
52	    let action_state = use_state(|| ActionState::Idle);
53	
54	    // ── Fetch versions on mount ──────────────────────────────────────────────
55	    {
56	        let ps  = page_state.clone();
57	        let tid = template_id;
58	        use_effect_with((), move |_| {
59	            spawn_local(async move {
60	                match ops_service::list_versions(tid).await {
61	                    Ok(data) => {
62	                        // The API returns a ListResponse wrapper
63	                        let versions: Vec<ConfigVersion> =
64	                            data.get("data")
65	                                .and_then(|v| serde_json::from_value(v.clone()).ok())
66	                                .unwrap_or_default();
67	                        ps.set(PageState::Loaded(versions));
68	                    }
69	                    Err(e) => ps.set(PageState::Error(e)),
70	                }
71	            });
72	            || ()
73	        });
74	    }
75	
76	    // ── Action handlers ──────────────────────────────────────────────────────
77	
78	    let do_publish = {
79	        let action_state = action_state.clone();
80	        let template_id  = template_id;
81	        Callback::from(move |version_id: Uuid| {
82	            let ast = action_state.clone();
83	            let tid = template_id;
84	            spawn_local(async move {
85	                ast.set(ActionState::Working);
86	                match ops_service::publish_version(tid, version_id).await {
87	                    Ok(_)  => ast.set(ActionState::Done("Version published".to_string())),
88	                    Err(e) => {
89	                        if e.contains("[403]") {
90	                            ast.set(ActionState::ReauthRequired {
91	                                action: PendingAction::Publish,
92	                                version_id,
93	                                template_id: tid,
94	                            });
95	                        } else {
96	                            ast.set(ActionState::Failed(e));
97	                        }
98	                    }
99	                }
100	            });
101	        })
102	    };
103	
104	    let do_unpublish = {
105	        let action_state = action_state.clone();
106	        let template_id  = template_id;
107	        Callback::from(move |version_id: Uuid| {
108	            let ast = action_state.clone();
109	            let tid = template_id;
110	            spawn_local(async move {
111	                ast.set(ActionState::Working);
112	                match ops_service::unpublish_version(tid, version_id).await {
113	                    Ok(_)  => ast.set(ActionState::Done("Version unpublished".to_string())),
114	                    Err(e) => {
115	                        if e.contains("[403]") {
116	                            ast.set(ActionState::ReauthRequired {
117	                                action: PendingAction::Unpublish,
118	                                version_id,
119	                                template_id: tid,
120	                            });
121	                        } else {
122	                            ast.set(ActionState::Failed(e));
123	                        }
124	                    }
125	                }
126	            });
127	        })
128	    };
129	
130	    // ── Render ───────────────────────────────────────────────────────────────
131	
132	    let content = match &*page_state {
133	        PageState::Loading => html! {
134	            <div class="loading-state">
135	                <div class="spinner" />
136	                <p>{ "Loading config versions…" }</p>
137	            </div>
138	        },
139	        PageState::Error(e) => html! {
140	            <div class="error-state">
141	                <p class="error-state__message">{ format!("Error loading versions: {}", e) }</p>
142	                <p>{ "Check your connection and try refreshing." }</p>
143	            </div>
144	        },
145	        PageState::Loaded(versions) if versions.is_empty() => html! {
146	            <div class="empty-state">
147	                <p class="empty-state__message">{ "No config versions found." }</p>
148	                <p>{ "Create a draft version to get started." }</p>
149	                <button class="btn btn--primary">{ "Create Draft" }</button>
150	            </div>
151	        },
152	        PageState::Loaded(versions) => {
153	            let pub_cb   = do_publish.clone();
154	            let unpub_cb = do_unpublish.clone();
155	            html! {
156	                <table class="data-table">
157	                    <thead>
158	                        <tr>
159	                            <th>{ "Version" }</th>
160	                            <th>{ "Status" }</th>
161	                            <th>{ "Published At" }</th>
162	                            <th>{ "Effective From" }</th>
163	                            <th>{ "Actions" }</th>
164	                        </tr>
165	                    </thead>
166	                    <tbody>
167	                        { for versions.iter().map(|v| {
168	                            let vid      = v.id;
169	                            let is_draft = v.is_draft();
170	                            let is_pub   = v.is_published();
171	                            let pub_cb2  = pub_cb.clone();
172	                            let upub_cb2 = unpub_cb.clone();
173	                            html! {
174	                                <tr key={vid.to_string()}>
175	                                    <td>{ format!("v{}", v.version_number) }</td>
176	                                    <td>
177	                                        <span class={format!("badge badge--{}", v.status)}>
178	                                            { v.status_label() }
179	                                        </span>
180	                                    </td>
181	                                    <td>
182	                                        { v.published_at.map(|t| t.format("%Y-%m-%d %H:%M UTC").to_string())
183	                                           .unwrap_or_else(|| "—".to_string()) }
184	                                    </td>
185	                                    <td>
186	                                        { v.effective_from.map(|t| t.format("%Y-%m-%d").to_string())
187	                                           .unwrap_or_else(|| "—".to_string()) }
188	                                    </td>
189	                                    <td class="action-cell">
190	                                        if is_draft {
191	                                            <button class="btn btn--small btn--primary"
192	                                                    onclick={Callback::from(move |_| pub_cb2.emit(vid))}>
193	                                                { "Publish" }
194	                                            </button>
195	                                        }
196	                                        if is_pub {
197	                                            <button class="btn btn--small btn--danger"
198	                                                    onclick={Callback::from(move |_| upub_cb2.emit(vid))}>
199	                                                { "Unpublish" }
200	                                            </button>
201	                                        }
202	                                    </td>
203	                                </tr>
204	                            }
205	                        }) }
206	                    </tbody>
207	                </table>
208	            }
209	        }
210	    };
211	
212	    // ── Action feedback ───────────────────────────────────────────────────────
213	
214	    let feedback = match &*action_state {
215	        ActionState::Working => html! {
216	            <div class="action-feedback action-feedback--working">{ "Working…" }</div>
217	        },
218	        ActionState::Done(msg) => html! {
219	            <div class="action-feedback action-feedback--success">{ msg }</div>
220	        },
221	        ActionState::Failed(e) => html! {
222	            <div class="action-feedback action-feedback--error">{ e }</div>
223	        },
224	        _ => html! {}
225	    };
226	
227	    // ── Reauth prompt overlay ─────────────────────────────────────────────────
228	
229	    let reauth_overlay = if let ActionState::ReauthRequired { action, version_id, template_id } = &*action_state {
230	        let action      = action.clone();
231	        let vid         = *version_id;
232	        let tid         = *template_id;
233	        let ast         = action_state.clone();
234	        let pub_cb_re   = do_publish.clone();
235	        let unpub_cb_re = do_unpublish.clone();
236	
237	        html! {
238	            <ReauthPrompt
239	                on_success={Callback::from(move |_| {
240	                    // Retry the original action after successful reauth
241	                    match action {
242	                        PendingAction::Publish   => pub_cb_re.emit(vid),
243	                        PendingAction::Unpublish => unpub_cb_re.emit(vid),
244	                    }
245	                })}
246	                on_cancel={Callback::from(move |_| ast.set(ActionState::Idle))}
247	            />
248	        }
249	    } else {
250	        html! {}
251	    };
252	
253	    html! {
254	        <div class="page">
255	            <header class="page__header">
256	                <h1 class="page__title">{ "Config Versions" }</h1>
257	                <div class="page__actions">
258	                    <button class="btn btn--primary">{ "+ New Draft" }</button>
259	                </div>
260	            </header>
261	
262	            { feedback }
263	
264	            <div class="page__body">
265	                { content }
266	            </div>
267	
268	            { reauth_overlay }
269	        </div>
270	    }
271	}
