1	/// Reporting: KPI metric definitions page.
2	///
3	/// Lists defined metrics, allows creating/deleting them.
4	/// Create and delete are reauth-gated (server returns 403 on stale session).
5	use wasm_bindgen_futures::spawn_local;
6	use yew::prelude::*;
7	
8	use crate::{
9	    components::reauth_prompt::ReauthPrompt,
10	    services::reporting_service,
11	    types::reporting::{CreateMetricRequest, MetricDefinition},
12	};
13	
14	#[derive(Clone, PartialEq)]
15	enum PageState { Loading, Loaded(Vec<MetricDefinition>), Error(String) }
16	
17	#[derive(Clone, PartialEq)]
18	enum ActionState { Idle, Working, ReauthRequired, Done(String), Failed(String) }
19	
20	#[function_component(MetricsPage)]
21	pub fn metrics_page() -> Html {
22	    let page_state   = use_state(|| PageState::Loading);
23	    let action_state = use_state(|| ActionState::Idle);
24	    let key_input    = use_state(String::new);
25	    let name_input   = use_state(String::new);
26	    let pending_del  = use_state::<Option<uuid::Uuid>, _>(|| None);
27	
28	    let reload = {
29	        let ps = page_state.clone();
30	        move || {
31	            let ps = ps.clone();
32	            spawn_local(async move {
33	                match reporting_service::list_metrics().await {
34	                    Ok(items) => ps.set(PageState::Loaded(items)),
35	                    Err(e)    => ps.set(PageState::Error(e)),
36	                }
37	            });
38	        }
39	    };
40	
41	    { let r = reload.clone(); use_effect_with((), move |_| { r(); || () }); }
42	
43	    let create_metric = {
44	        let ast   = action_state.clone();
45	        let key   = key_input.clone();
46	        let name  = name_input.clone();
47	        let rel   = reload.clone();
48	        Callback::from(move |e: SubmitEvent| {
49	            e.prevent_default();
50	            let body = CreateMetricRequest {
51	                metric_key:   (*key).clone(),
52	                display_name: (*name).clone(),
53	                description:  None,
54	                formula_type: "custom_sql".to_string(),
55	            };
56	            let ast2 = ast.clone();
57	            let rel2 = rel.clone();
58	            spawn_local(async move {
59	                ast2.set(ActionState::Working);
60	                match reporting_service::create_metric(&body).await {
61	                    Ok(_)  => { ast2.set(ActionState::Done("Metric created".into())); rel2(); }
62	                    Err(e) if e.contains("[403]") => ast2.set(ActionState::ReauthRequired),
63	                    Err(e) => ast2.set(ActionState::Failed(e)),
64	                }
65	            });
66	        })
67	    };
68	
69	    let delete_metric = {
70	        let ast  = action_state.clone();
71	        let pend = pending_del.clone();
72	        let rel  = reload.clone();
73	        Callback::from(move |mid: uuid::Uuid| {
74	            let ast2  = ast.clone();
75	            let rel2  = rel.clone();
76	            pend.set(Some(mid));
77	            spawn_local(async move {
78	                ast2.set(ActionState::Working);
79	                match reporting_service::delete_metric(mid).await {
80	                    Ok(_)  => { ast2.set(ActionState::Done("Metric deleted".into())); rel2(); }
81	                    Err(e) if e.contains("[403]") => ast2.set(ActionState::ReauthRequired),
82	                    Err(e) => ast2.set(ActionState::Failed(e)),
83	                }
84	            });
85	        })
86	    };
87	
88	    let content = match &*page_state {
89	        PageState::Loading => html! { <div class="loading-state"><div class="spinner"/></div> },
90	        PageState::Error(e) => html! { <p class="error-state__message">{ e }</p> },
91	        PageState::Loaded(items) if items.is_empty() => html! {
92	            <div class="empty-state"><p>{ "No metrics defined." }</p></div>
93	        },
94	        PageState::Loaded(items) => {
