1	/// Reporting: Scheduled report management page.
2	///
3	/// Lists scheduled reports, allows creating/deleting schedules and
4	/// triggering a manual run.  All mutations are reauth-gated.
5	use uuid::Uuid;
6	use wasm_bindgen_futures::spawn_local;
7	use yew::prelude::*;
8	
9	use crate::{
10	    components::reauth_prompt::ReauthPrompt,
11	    services::reporting_service,
12	    types::reporting::{CreateScheduledReportRequest, ScheduledReport},
13	};
14	
15	#[derive(Clone, PartialEq)]
16	enum PageState { Loading, Loaded(Vec<ScheduledReport>), Error(String) }
17	
18	#[derive(Clone, PartialEq)]
19	enum ActionState {
20	    Idle,
21	    Working,
22	    ReauthRequired { pending: PendingAction },
23	    Done(String),
24	    Failed(String),
25	}
26	
27	#[derive(Clone, PartialEq)]
28	enum PendingAction { Delete(Uuid), Trigger(Uuid) }
29	
30	#[function_component(SchedulesPage)]
31	pub fn schedules_page() -> Html {
32	    let page_state   = use_state(|| PageState::Loading);
33	    let action_state = use_state(|| ActionState::Idle);
34	    let name_input   = use_state(|| "Weekly Report".to_string());
35	    let cron_input   = use_state(|| "0 8 * * 1".to_string());
36	
37	    let reload = {
38	        let ps = page_state.clone();
39	        move || {
40	            let ps = ps.clone();
41	            spawn_local(async move {
42	                match reporting_service::list_schedules().await {
43	                    Ok(items) => ps.set(PageState::Loaded(items)),
44	                    Err(e)    => ps.set(PageState::Error(e)),
45	                }
46	            });
47	        }
48	    };
49	
50	    { let r = reload.clone(); use_effect_with((), move |_| { r(); || () }); }
51	
52	    let handle_err = {
53	        let ast = action_state.clone();
54	        move |e: String, pending: PendingAction| {
55	            if e.contains("[403]") {
56	                ast.set(ActionState::ReauthRequired { pending });
57	            } else {
58	                ast.set(ActionState::Failed(e));
59	            }
60	        }
61	    };
62	
63	    let create_schedule = {
64	        let ast   = action_state.clone();
65	        let ni    = name_input.clone();
66	        let ci    = cron_input.clone();
67	        let rel   = reload.clone();
68	        let herr  = handle_err.clone();
69	        Callback::from(move |e: SubmitEvent| {
70	            e.prevent_default();
71	            let body = CreateScheduledReportRequest {
72	                name:            (*ni).clone(),
73	                metric_ids:      vec![],
74	                schedule:        (*ci).clone(),
75	                date_range_days: Some(30),
76	                output_format:   Some("csv".to_string()),
77	            };
78	            let ast2  = ast.clone();
79	            let rel2  = rel.clone();
80	            let herr2 = herr.clone();
81	            spawn_local(async move {
82	                ast2.set(ActionState::Working);
83	                match reporting_service::create_schedule(&body).await {
84	                    Ok(_)  => { ast2.set(ActionState::Done("Schedule created".into())); rel2(); }
85	                    Err(e) => herr2(e, PendingAction::Delete(Uuid::nil())), // reuse error path
86	                }
87	            });
88	        })
89	    };
90	
91	    let delete_schedule = {
92	        let ast  = action_state.clone();
93	        let rel  = reload.clone();
94	        let herr = handle_err.clone();
95	        Callback::from(move |sid: Uuid| {
96	            let ast2  = ast.clone();
97	            let rel2  = rel.clone();
98	            let herr2 = herr.clone();
99	            spawn_local(async move {
100	                ast2.set(ActionState::Working);
101	                match reporting_service::delete_schedule(sid).await {
102	                    Ok(_)  => { ast2.set(ActionState::Done("Schedule deleted".into())); rel2(); }
103	                    Err(e) => herr2(e, PendingAction::Delete(sid)),
104	                }
105	            });
106	        })
107	    };
108	
109	    let trigger_run = {
110	        let ast  = action_state.clone();
111	        let herr = handle_err.clone();
112	        Callback::from(move |sid: Uuid| {
113	            let ast2  = ast.clone();
114	            let herr2 = herr.clone();
115	            spawn_local(async move {
116	                ast2.set(ActionState::Working);
117	                match reporting_service::trigger_run(sid).await {
118	                    Ok(_)  => ast2.set(ActionState::Done("Run triggered".into())),
119	                    Err(e) => herr2(e, PendingAction::Trigger(sid)),
120	                }
121	            });
122	        })
123	    };
124	
125	    let content = match &*page_state {
126	        PageState::Loading => html! { <div class="loading-state"><div class="spinner"/></div> },
127	        PageState::Error(e) => html! { <p class="error-state__message">{ e }</p> },
128	        PageState::Loaded(items) if items.is_empty() => html! {
129	            <div class="empty-state"><p>{ "No scheduled reports." }</p></div>
130	        },
131	        PageState::Loaded(items) => {
132	            let del  = delete_schedule.clone();
133	            let trig = trigger_run.clone();
134	            html! {
135	                <table class="data-table">
136	                    <thead>
137	                        <tr>
138	                            <th>{ "Name" }</th>
139	                            <th>{ "Schedule" }</th>
140	                            <th>{ "Format" }</th>
141	                            <th>{ "Next Run" }</th>
142	                            <th>{ "Active" }</th>
143	                            <th>{ "Actions" }</th>
144	                        </tr>
145	                    </thead>
146	                    <tbody>
147	                        { for items.iter().map(|s| {
148	                            let sid   = s.id;
149	                            let del2  = del.clone();
150	                            let trig2 = trig.clone();
151	                            html! {
152	                                <tr key={sid.to_string()}>
153	                                    <td>{ &s.name }</td>
154	                                    <td class="mono">{ &s.schedule }</td>
155	                                    <td>{ &s.output_format }</td>
156	                                    <td>
157	                                        { s.next_run_at
158	                                            .map(|t| t.format("%Y-%m-%d %H:%M").to_string())
159	                                            .unwrap_or_else(|| "—".to_string()) }
160	                                    </td>
161	                                    <td>{ if s.is_active { "Yes" } else { "No" } }</td>
162	                                    <td class="action-cell">
163	                                        <button class="btn btn--small btn--secondary"
164	                                                onclick={Callback::from(move |_| trig2.emit(sid))}>
165	                                            { "Run Now" }
166	                                        </button>
167	                                        <button class="btn btn--small btn--danger"
168	                                                onclick={Callback::from(move |_| del2.emit(sid))}>
169	                                            { "Delete" }
170	                                        </button>
171	                                    </td>
172	                                </tr>
173	                            }
174	                        }) }
175	                    </tbody>
176	                </table>
177	            }
178	        }
179	    };
180	
181	    let feedback = match &*action_state {
182	        ActionState::Working   => html! { <div class="action-feedback action-feedback--working">{ "Working…" }</div> },
183	        ActionState::Done(msg) => html! { <div class="action-feedback action-feedback--success">{ msg }</div> },
184	        ActionState::Failed(e) => html! { <div class="action-feedback action-feedback--error">{ e }</div> },
185	        _ => html! {},
186	    };
187	
188	    let reauth_overlay = if let ActionState::ReauthRequired { pending } = &*action_state {
189	        let pending  = pending.clone();
190	        let ast      = action_state.clone();
191	        let del_cb   = delete_schedule.clone();
192	        let trig_cb  = trigger_run.clone();
193	        html! {
194	            <ReauthPrompt
195	                on_success={Callback::from(move |_| {
196	                    match &pending {
197	                        PendingAction::Delete(id)  => del_cb.emit(*id),
198	                        PendingAction::Trigger(id) => trig_cb.emit(*id),
199	                    }
200	                })}
201	                on_cancel={Callback::from({
202	                    let ast = action_state.clone();
203	                    move |_| ast.set(ActionState::Idle)
204	                })}
205	            />
206	        }
207	    } else { html! {} };
208	
209	    html! {
210	        <div class="page">
211	            <header class="page__header">
212	                <h1 class="page__title">{ "Report Schedules" }</h1>
213	            </header>
214	            <div class="page__body">
215	                <form onsubmit={create_schedule} class="inline-form">
216	                    <label class="form-field form-field--inline">
217	                        <span>{ "Name" }</span>
218	                        <input type="text"
219	                               value={(*name_input).clone()}
220	                               oninput={{
221	                                   let n = name_input.clone();
222	                                   Callback::from(move |e: InputEvent| {
223	                                       let el: web_sys::HtmlInputElement = e.target_unchecked_into();
224	                                       n.set(el.value());
225	                                   })
226	                               }}
227	                               class="form-field__input" />
228	                    </label>
229	                    <label class="form-field form-field--inline">
230	                        <span>{ "Cron" }</span>
231	                        <input type="text"
232	                               value={(*cron_input).clone()}
233	                               oninput={{
234	                                   let c = cron_input.clone();
235	                                   Callback::from(move |e: InputEvent| {
236	                                       let el: web_sys::HtmlInputElement = e.target_unchecked_into();
237	                                       c.set(el.value());
238	                                   })
239	                               }}
240	                               class="form-field__input" />
241	                    </label>
242	                    <button type="submit" class="btn btn--primary">{ "Schedule" }</button>
243	                </form>
244	                { feedback }
