113	// ── Rollout page state transitions ───────────────────────────────────────────
114	
115	mod rollout_page_states {
116	    use super::*;
117	    use chrono::Utc;
118	    use uuid::Uuid;
119	
120	    // Mirror the page's state enums to test transition logic without mounting DOM
121	    #[derive(Clone, PartialEq, Debug)]
122	    enum PageState { Empty, Loading, Loaded(RolloutPlan), Error(String) }
123	
124	    #[derive(Clone, PartialEq, Debug)]
125	    enum ActionState {
126	        Idle,
127	        Working,
128	        ReauthRequired { stage_id: Uuid, plan_id: Uuid, template_id: Uuid },
129	        Done(String),
130	        Failed(String),
131	    }
132	
133	    fn make_plan(status: &str, num_stages: usize) -> RolloutPlan {
134	        RolloutPlan {
135	            id:                Uuid::new_v4(),
136	            config_version_id: Uuid::new_v4(),
137	            status:            status.to_string(),
138	            total_depots:      100,
139	            current_stage:     0,
140	            stages:            (0..num_stages)
141	                .map(|i| RolloutStage {
142	                    id:                Uuid::new_v4(),
143	                    stage_number:      (i + 1) as i16,
144	                    target_percentage: ((i + 1) * 33) as i16,
145	                    depot_count:       33,
146	                    status:            "pending".to_string(),
147	                    scheduled_at:      None,
148	                    activated_at:      None,
149	                })
150	                .collect(),
151	            created_at: Utc::now(),
152	        }
153	    }
154	
155	    fn simulate_load(result: Result<RolloutPlan, String>) -> PageState {
156	        match result {
157	            Ok(plan) => PageState::Loaded(plan),
158	            Err(e)   => PageState::Error(e),
159	        }
160	    }
161	
162	    fn simulate_activate(
163	        result:   Result<(), String>,
164	        stage_id: Uuid,
165	        pid:      Uuid,
166	        tid:      Uuid,
167	    ) -> ActionState {
168	        match result {
169	            Ok(_)                          => ActionState::Done("Stage activated successfully.".to_string()),
170	            Err(e) if e.contains("[403]") => ActionState::ReauthRequired {
171	                stage_id, plan_id: pid, template_id: tid,
172	            },
173	            Err(e) => ActionState::Failed(e),
174	        }
