504	// ── Base64 encoder correctness ────────────────────────────────────────────────
505	
506	mod base64_encoding {
507	    use super::*;
508	
509	    /// Exact copy of the inline encoder from `statements.rs`.
510	    /// Kept here to verify correctness independently of the DOM.
511	    fn to_base64(data: &[u8]) -> String {
512	        const TABLE: &[u8; 64] =
513	            b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
514	        let mut out = String::with_capacity((data.len() + 2) / 3 * 4);
515	        for chunk in data.chunks(3) {
516	            let n = (chunk[0] as u32) << 16
517	                | (if chunk.len() > 1 { chunk[1] as u32 } else { 0 }) << 8
518	                | (if chunk.len() > 2 { chunk[2] as u32 } else { 0 });
519	            out.push(TABLE[((n >> 18) & 63) as usize] as char);
520	            out.push(TABLE[((n >> 12) & 63) as usize] as char);
521	            out.push(if chunk.len() > 1 { TABLE[((n >> 6) & 63) as usize] as char } else { '=' });
522	            out.push(if chunk.len() > 2 { TABLE[(n & 63) as usize] as char } else { '=' });
523	        }
524	        out
525	    }
526	
527	    #[wasm_bindgen_test]
528	    fn encodes_empty_input_to_empty_string() {
529	        assert_eq!(to_base64(b""), "");
530	    }
531	
532	    #[wasm_bindgen_test]
533	    fn encodes_single_byte_m() {
534	        // "M" → "TQ=="  (RFC 4648 known vector)
535	        assert_eq!(to_base64(b"M"), "TQ==");
536	    }
537	
538	    #[wasm_bindgen_test]
539	    fn encodes_two_bytes_ma() {
540	        // "Ma" → "TWE="
541	        assert_eq!(to_base64(b"Ma"), "TWE=");
542	    }
543	
544	    #[wasm_bindgen_test]
545	    fn encodes_three_bytes_man() {
546	        // "Man" → "TWFu"
547	        assert_eq!(to_base64(b"Man"), "TWFu");
548	    }
549	
550	    #[wasm_bindgen_test]
551	    fn encodes_hello_world() {
552	        // Known-good vector
553	        assert_eq!(to_base64(b"Hello, World!"), "SGVsbG8sIFdvcmxkIQ==");
554	    }
555	
556	    #[wasm_bindgen_test]
557	    fn output_length_is_always_multiple_of_four() {
558	        for len in 0_usize..=20 {
559	            let data = vec![0xABu8; len];
560	            let encoded = to_base64(&data);
561	            assert_eq!(
562	                encoded.len() % 4,
563	                0,
564	                "base64 output must be a multiple of 4, failed for input len={}",
