                                </button>
                            </div>
                        </form>
                    </div>
                </div>
            }
        }
        FormState::Hidden => html! {}
    };

    html! {
        <div class="page">
            <header class="page__header">
                <h1 class="page__title">{ "Fare Rules" }</h1>
