        },
        PageState::Loaded(runs) => {
            html! {
                <table class="data-table">
                    <thead>
                        <tr>
                            <th>{ "Started" }</th>
                            <th>{ "Status" }</th>
                            <th>{ "Format" }</th>
                            <th>{ "Period" }</th>
                            <th>{ "Completed" }</th>
                            <th>{ "Export" }</th>
                        </tr>
                    </thead>
                    <tbody>
                        { for runs.iter().map(|r| {
                            let run_id     = r.id;
                            let is_done    = r.is_completed();
                            let status_cls = if r.is_completed() { "badge--published" }
                                           else if r.is_running() { "badge--scheduled" }
                                           else { "badge--draft" };
                            let csv_url  = reporting_service::export_run_url(run_id, "csv");
                            let pdf_url  = reporting_service::export_run_url(run_id, "pdf");
                            // export_run_url is sync now — we use the String directly
                            html! {
                                <tr key={run_id.to_string()}>
                                    <td>{ r.started_at.format("%Y-%m-%d %H:%M").to_string() }</td>
                                    <td>
                                        <span class={format!("badge {}", status_cls)}>
                                            { &r.status }
                                        </span>
                                    </td>
                                    <td class="mono">{ &r.output_format }</td>
                                    <td>
                                        { format!(
                                            "{} – {}",
                                            r.date_from.format("%Y-%m-%d"),
                                            r.date_to.format("%Y-%m-%d"),
                                        ) }
                                    </td>
                                    <td>
                                        { r.completed_at
                                            .map(|t| t.format("%Y-%m-%d %H:%M").to_string())
                                            .unwrap_or_else(|| "—".to_string()) }
                                    </td>
                                    <td class="action-cell">
                                        if is_done {
                                            <a href={csv_url}
                                               download=""
                                               class="btn btn--small btn--secondary">
                                                { "CSV" }
                                            </a>
                                            { " " }
                                            <a href={pdf_url}
                                               download=""
                                               class="btn btn--small btn--secondary">
                                                { "PDF" }
                                            </a>
                                        }
                                    </td>
                                </tr>
                            }
                        }) }
                    </tbody>
                </table>
            }
        }
    };

    html! {
        <div class="page">
            <header class="page__header">
                <h1 class="page__title">{ "Report Runs" }</h1>
                <div class="page__actions">
                    <button class="btn btn--secondary" onclick={on_refresh}>
                        { "Refresh" }
                    </button>
                </div>
            </header>
            <div class="page__body">
                { content }
            </div>
        </div>
    }
}
"}

