{"file_path": "C:\Users\user\Desktop\eaglepoint_new\Week-2\TASK-62\repo\frontend\src\pages\ops\config_list.rs", "content": "/// Ops config version list page.
///
/// Shows all config versions for available templates.  Supports:
///   - Loading / empty / error states
///   - Publish / unpublish / schedule actions (admin only)
///     → triggers ReauthPrompt when server returns 403
///   - Link to diff view and rollout manager
use chrono::{DateTime, NaiveDateTime, Utc};
use uuid::Uuid;
use wasm_bindgen_futures::spawn_local;
use yew::prelude::*;

use crate::{
    components::reauth_prompt::ReauthPrompt,
    services::ops_service,
    types::ops::{ConfigVersion, ScheduleVersionRequest},
};

// ── Page state ────────────────────────────────────────────────────────────────

#[derive(Clone, PartialEq)]
enum PageState {
    Loading,
    Loaded(Vec<ConfigVersion>),
    Error(String),
}

#[derive(Clone, PartialEq)]
enum ActionState {
    Idle,
    Confirming { action: PendingAction, version_id: Uuid, template_id: Uuid },
    ReauthRequired { action: PendingAction, version_id: Uuid, template_id: Uuid },
    Working,
    Done(String),
    Failed(String),
}

#[derive(Clone, PartialEq, Debug)]
enum PendingAction { Publish, Unpublish, Schedule }

// ── Helper: parse a datetime-local string ("YYYY-MM-DDTHH:MM") into DateTime<Utc> ──

fn parse_schedule_dt(s: &str) -> Option<DateTime<Utc>> {
    NaiveDateTime::parse_from_str(s, "%Y-%m-%dT%H:%M")
        .ok()
        .map(|ndt| DateTime::from_naive_utc_and_offset(ndt, Utc))
}

// ── Component ─────────────────────────────────────────────────────────────────

/// Hardcoded known template IDs for the common config areas.
/// In production these would be fetched from GET /ops/configs/templates.
const DEMO_TEMPLATE_ID: &str = "00000000-0000-0000-0000-000000000001";

#[function_component(ConfigListPage)]
pub fn config_list_page() -> Html {
    // For demo purposes, use a fixed template_id; in production fetch templates first.
    let template_id: Uuid = DEMO_TEMPLATE_ID.parse().unwrap_or(Uuid::nil());

    let page_state       = use_state(|| PageState::Loading);
    let action_state     = use_state(|| ActionState::Idle);
    let schedule_open    = use_state::<Option<Uuid>, _>(|| None); // which version has form open
    let schedule_dt_inp  = use_state(String::new);                // datetime-local input value

    // ── Fetch versions on mount ──────────────────────────────────────────────
    {
        let ps  = page_state.clone();
        let tid = template_id;
        use_effect_with((), move |_| {
            spawn_local(async move {
                match ops_service::list_versions(tid).await {
                    Ok(data) => {
                        let versions: Vec<ConfigVersion> =
                            data.get("data")
                                .and_then(|v| serde_json::from_value(v.clone()).ok())
                                .unwrap_or_default();
                        ps.set(PageState::Loaded(versions));
                    }
                    Err(e) => ps.set(PageState::Error(e)),
                }
            });
            || ()
        });
    }

    // ── Action handlers ──────────────────────────────────────────────────────

    let do_publish = {
        let action_state = action_state.clone();
        let template_id  = template_id;
        Callback::from(move |version_id: Uuid| {
            let ast = action_state.clone();
            let tid = template_id;
            spawn_local(async move {
                ast.set(ActionState::Working);
                match ops_service::publish_version(tid, version_id).await {
                    Ok(_)  => ast.set(ActionState::Done("Version published".to_string())),
                    Err(e) => {
                        if e.contains("[403]") {
                            ast.set(ActionState::ReauthRequired {
                                action: PendingAction::Publish,
                                version_id,
                                template_id: tid,
                            });
                        } else {
                            ast.set(ActionState::Failed(e));
                        }
                    }
                }
            });
        })
    };

    let do_unpublish = {
        let action_state = action_state.clone();
        let template_id  = template_id;
        Callback::from(move |version_id: Uuid| {
            let ast = action_state.clone();
            let tid = template_id;
            spawn_local(async move {
                ast.set(ActionState::Working);
                match ops_service::unpublish_version(tid, version_id).await {
                    Ok(_)  => ast.set(ActionState::Done("Version unpublished".to_string())),
                    Err(e) => {
                        if e.contains("[403]") {
                            ast.set(ActionState::ReauthRequired {
                                action: PendingAction::Unpublish,
                                version_id,
                                template_id: tid,
                            });
                        } else {
                            ast.set(ActionState::Failed(e));
                        }
                    }
                }
            });
        })
    };

    let do_schedule = {
        let action_state = action_state.clone();
        let schedule_dt  = schedule_dt_inp.clone();
        let sched_open   = schedule_open.clone();
        let template_id  = template_id;
        Callback::from(move |version_id: Uuid| {
            let dt_str = (*schedule_dt).clone();
            let effective_from = match parse_schedule_dt(&dt_str) {
                Some(dt) => dt,
                None => {
                    action_state.set(ActionState::Failed(
                        "Invalid date — use the date/time picker.".to_string(),
                    ));
                    return;
                }
            };
            let body = ScheduleVersionRequest { effective_from, effective_to: None };
            let ast  = action_state.clone();
            let tid  = template_id;
            let so   = sched_open.clone();
            spawn_local(async move {
                so.set(None); // close the inline form
                ast.set(ActionState::Working);
                match ops_service::schedule_version(tid, version_id, &body).await {
                    Ok(_)  => ast.set(ActionState::Done("Version scheduled".to_string())),
                    Err(e) => {
