1	/// Role-aware route guard.
2	///
3	/// Wraps page content and redirects unauthenticated users to /login.
4	/// Optionally checks that the current role satisfies a predicate; if not,
5	/// renders a "403 Forbidden" banner instead of the page content.
6	use yew::prelude::*;
7	use yew_router::prelude::*;
8	
9	use crate::{
10	    pages::Route,
11	    store::auth_store::AuthContext,
12	    types::auth::SessionInfo,
13	};
14	
15	// ── AuthGuard — authentication only ──────────────────────────────────────────
16	
17	/// Renders `children` only when the user is authenticated.
18	/// Redirects to `/login` otherwise.
19	#[derive(Properties, PartialEq)]
20	pub struct AuthGuardProps {
21	    pub children: Children,
22	}
23	
24	#[function_component(AuthGuard)]
25	pub fn auth_guard(props: &AuthGuardProps) -> Html {
26	    let auth = use_context::<AuthContext>().expect("AuthContext missing");
27	
28	    if auth.loading {
29	        return html! { <div class="loading-screen">{ "Loading…" }</div> };
30	    }
31	
32	    if !auth.is_authenticated() {
33	        return html! { <Redirect<Route> to={Route::Login} /> };
34	    }
35	
36	    html! { { for props.children.iter() } }
37	}
38	
39	// ── RoleGuard — role-predicate check ─────────────────────────────────────────
40	
41	/// Renders `children` only when the user is authenticated AND the role
42	/// satisfies `allowed`.  Shows a 403 message otherwise.
43	#[derive(Properties, PartialEq)]
44	pub struct RoleGuardProps {
45	    pub children: Children,
46	    /// Predicate run against the current `SessionInfo`.
47	    pub allowed:  Callback<SessionInfo, bool>,
48	}
49	
50	#[function_component(RoleGuard)]
51	pub fn role_guard(props: &RoleGuardProps) -> Html {
52	    let auth = use_context::<AuthContext>().expect("AuthContext missing");
53	
54	    if auth.loading {
55	        return html! { <div class="loading-screen">{ "Loading…" }</div> };
56	    }
57	
58	    if !auth.is_authenticated() {
59	        return html! { <Redirect<Route> to={Route::Login} /> };
60	    }
61	
62	    let session = auth.session.as_ref().cloned().unwrap_or_default();
63	    if props.allowed.emit(session) {
64	        html! { { for props.children.iter() } }
65	    } else {
66	        html! {
67	            <div class="error-page error-page--403">
68	                <h1>{ "403 — Access Denied" }</h1>
69	                <p>{ "Your role does not have permission to access this area." }</p>
70	                <Link<Route> to={Route::Inbox}>{ "Return to inbox" }</Link<Route>>
71	            </div>
72	        }
73	    }
74	}
