1	/// Sidebar navigation with role-aware link visibility.
2	///
3	/// Each nav item is shown or hidden based on the current user's role.
4	/// Active route is highlighted via CSS class matching.
5	/// Sign-out dispatches `AuthAction::Logout`, calls the logout API (best-effort),
6	/// then navigates to `/login`.
7	use wasm_bindgen_futures::spawn_local;
8	use yew::prelude::*;
9	use yew_router::prelude::*;
10	
11	use crate::{
12	    pages::Route,
13	    services::auth_service,
14	    store::auth_store::{AuthAction, AuthContext},
15	};
16	
17	#[function_component(NavSidebar)]
18	pub fn nav_sidebar() -> Html {
19	    let auth      = use_context::<AuthContext>().expect("AuthContext missing");
20	    let navigator = use_navigator();
21	    let session   = auth.session.as_ref();
22	
23	    let role = session.map(|s| s.role.as_str()).unwrap_or("");
24	
25	    // Role capability flags
26	    let is_admin      = role == "operations_admin";
27	    let is_dispatcher = role == "dispatcher";
28	    let is_finance    = role == "finance_analyst";
29	    let can_ops       = matches!(role, "operations_admin" | "dispatcher");
30	    let can_finance   = matches!(role, "operations_admin" | "finance_analyst");
31	    let can_reporting = true; // all authenticated roles
32	    let can_alerts    = matches!(role, "operations_admin" | "dispatcher" | "finance_analyst");
33	
34	    // ── Sign-out: dispatch Logout, fire-and-forget server call, navigate ─────
35	    let on_logout = {
36	        let auth = auth.clone();
37	        let nav  = navigator.clone();
38	        Callback::from(move |e: MouseEvent| {
39	            e.prevent_default();
40	            auth.dispatch(AuthAction::Logout);
41	            spawn_local(async { let _ = auth_service::logout().await; });
42	            if let Some(n) = nav.as_ref() {
43	                n.push(&Route::Login);
44	            }
45	        })
46	    };
47	
48	    html! {
49	        <nav class="sidebar">
50	            <div class="sidebar__brand">
51	                <span class="sidebar__brand-text">{ "TransitOps" }</span>
52	            </div>
53	
