1	/// Reporting: KPI metric definitions page.
2	///
3	/// Lists defined metrics, allows creating/deleting them.
4	/// Create and delete are reauth-gated (server returns 403 on stale session).
5	///
6	/// Clicking a metric row opens a drilldown panel where the user can specify a
7	/// date range and fetch computed values for that metric (with dimension breakdown).
8	use wasm_bindgen_futures::spawn_local;
9	use yew::prelude::*;
10	
11	use crate::{
12	    components::reauth_prompt::ReauthPrompt,
13	    services::reporting_service,
14	    types::reporting::{CreateMetricRequest, MetricDefinition, MetricValue},
15	};
16	
17	#[derive(Clone, PartialEq)]
18	enum PageState { Loading, Loaded(Vec<MetricDefinition>), Error(String) }
19	
20	#[derive(Clone, PartialEq)]
21	enum ActionState { Idle, Working, ReauthRequired, Done(String), Failed(String) }
22	
23	#[derive(Clone, PartialEq)]
24	enum DrilldownState { Idle, Loading, Loaded(Vec<MetricValue>), Error(String) }
25	
26	#[function_component(MetricsPage)]
27	pub fn metrics_page() -> Html {
28	    let page_state      = use_state(|| PageState::Loading);
29	    let action_state    = use_state(|| ActionState::Idle);
30	    let key_input       = use_state(String::new);
31	    let name_input      = use_state(String::new);
32	    let pending_del     = use_state::<Option<uuid::Uuid>, _>(|| None);
33	
34	    // Drilldown state
35	    let drilldown_metric = use_state::<Option<MetricDefinition>, _>(|| None);
36	    let drilldown_state  = use_state(|| DrilldownState::Idle);
37	    let drill_from       = use_state(|| "2025-01-01".to_string());
38	    let drill_to         = use_state(|| "2025-12-31".to_string());
39	
40	    let reload = {
41	        let ps = page_state.clone();
42	        move || {
43	            let ps = ps.clone();
44	            spawn_local(async move {
45	                match reporting_service::list_metrics().await {
46	                    Ok(items) => ps.set(PageState::Loaded(items)),
47	                    Err(e)    => ps.set(PageState::Error(e)),
48	                }
49	            });
50	        }
51	    };
52	
53	    { let r = reload.clone(); use_effect_with((), move |_| { r(); || () }); }
54	
55	    let create_metric = {
56	        let ast   = action_state.clone();
57	        let key   = key_input.clone();
58	        let name  = name_input.clone();
59	        let rel   = reload.clone();
60	        Callback::from(move |e: SubmitEvent| {
61	            e.prevent_default();
62	            let body = CreateMetricRequest {
63	                metric_key:   (*key).clone(),
64	                display_name: (*name).clone(),
65	                description:  None,
66	                formula_type: "custom_sql".to_string(),
67	            };
68	            let ast2 = ast.clone();
69	            let rel2 = rel.clone();
70	            spawn_local(async move {
71	                ast2.set(ActionState::Working);
72	                match reporting_service::create_metric(&body).await {
73	                    Ok(_)  => { ast2.set(ActionState::Done("Metric created".into())); rel2(); }
74	                    Err(e) if e.contains("[403]") => ast2.set(ActionState::ReauthRequired),
75	                    Err(e) => ast2.set(ActionState::Failed(e)),
76	                }
77	            });
78	        })
79	    };
80	
81	    let delete_metric = {
82	        let ast  = action_state.clone();
83	        let pend = pending_del.clone();
84	        let rel  = reload.clone();
85	        Callback::from(move |mid: uuid::Uuid| {
86	            let ast2  = ast.clone();
87	            let rel2  = rel.clone();
88	            pend.set(Some(mid));
89	            spawn_local(async move {
90	                ast2.set(ActionState::Working);
91	                match reporting_service::delete_metric(mid).await {
92	                    Ok(_)  => { ast2.set(ActionState::Done("Metric deleted".into())); rel2(); }
93	                    Err(e) if e.contains("[403]") => ast2.set(ActionState::ReauthRequired),
94	                    Err(e) => ast2.set(ActionState::Failed(e)),
95	                }
96	            });
97	        })
98	    };
99	
100	    // ── Drilldown fetch ───────────────────────────────────────────────────────
101	
102	    let fetch_drilldown = {
103	        let ds   = drilldown_state.clone();
104	        let dm   = drilldown_metric.clone();
105	        let from = drill_from.clone();
106	        let to   = drill_to.clone();
107	        Callback::from(move |e: SubmitEvent| {
108	            e.prevent_default();
109	            let metric_id = match (*dm).as_ref().map(|m| m.id) {
110	                Some(id) => id,
111	                None     => return,
112	            };
113	            let from_str = (*from).clone();
114	            let to_str   = (*to).clone();
115	            let ds2      = ds.clone();
116	            spawn_local(async move {
117	                ds2.set(DrilldownState::Loading);
118	                match reporting_service::get_metric_values(metric_id, &from_str, &to_str).await {
119	                    Ok(vals) => ds2.set(DrilldownState::Loaded(vals)),
120	                    Err(e)   => ds2.set(DrilldownState::Error(e)),
121	                }
122	            });
123	        })
124	    };
125	
126	    // ── Metric table ──────────────────────────────────────────────────────────
127	
128	    let content = match &*page_state {
129	        PageState::Loading => html! { <div class="loading-state"><div class="spinner"/></div> },
130	        PageState::Error(e) => html! { <p class="error-state__message">{ e }</p> },
131	        PageState::Loaded(items) if items.is_empty() => html! {
132	            <div class="empty-state"><p>{ "No metrics defined." }</p></div>
133	        },
134	        PageState::Loaded(items) => {
135	            let del = delete_metric.clone();
136	            let dm  = drilldown_metric.clone();
137	            let dds = drilldown_state.clone();
138	            html! {
139	                <table class="data-table">
140	                    <thead>
141	                        <tr>
142	                            <th>{ "Key" }</th>
143	                            <th>{ "Display Name" }</th>
144	                            <th>{ "Formula Type" }</th>
145	                            <th>{ "Builtin" }</th>
146	                            <th>{ "Actions" }</th>
147	                        </tr>
148	                    </thead>
149	                    <tbody>
150	                        { for items.iter().map(|m| {
151	                            let mid     = m.id;
152	                            let del2    = del.clone();
153	                            let dm2     = dm.clone();
154	                            let dds2    = dds.clone();
155	                            let builtin = m.is_builtin;
156	                            let metric  = m.clone();
157	                            html! {
158	                                <tr key={mid.to_string()}
159	                                    class="data-table__row--clickable"
160	                                    onclick={Callback::from(move |_| {
161	                                        dm2.set(Some(metric.clone()));
162	                                        dds2.set(DrilldownState::Idle);
163	                                    })}>
164	                                    <td class="mono">{ &m.metric_key }</td>
165	                                    <td>{ &m.display_name }</td>
166	                                    <td>{ m.formula_label() }</td>
167	                                    <td>{ if builtin { "Yes" } else { "No" } }</td>
168	                                    <td class="action-cell">
169	                                        if !builtin {
170	                                            <button class="btn btn--small btn--danger"
171	                                                    onclick={Callback::from(move |e: MouseEvent| {
172	                                                        e.stop_propagation();
173	                                                        del2.emit(mid);
174	                                                    })}>
175	                                                { "Delete" }
176	                                            </button>
177	                                        }
178	                                    </td>
179	                                </tr>
180	                            }
181	                        }) }
182	                    </tbody>
183	                </table>
184	            }
185	        }
186	    };
187	
188	    // ── Drilldown panel ───────────────────────────────────────────────────────
189	
190	    let drilldown_panel = if let Some(metric) = &*drilldown_metric {
191	        let ds_body = match &*drilldown_state {
192	            DrilldownState::Idle    => html! { <p class="hint">{ "Set a date range and click Fetch." }</p> },
193	            DrilldownState::Loading => html! { <div class="loading-state"><div class="spinner"/></div> },
194	            DrilldownState::Error(e) => html! { <p class="error-state__message">{ e }</p> },
195	            DrilldownState::Loaded(vals) if vals.is_empty() => html! {
196	                <p class="empty-state__message">{ "No values in the selected range." }</p>
197	            },
198	            DrilldownState::Loaded(vals) => html! {
199	                <table class="data-table data-table--sm">
200	                    <thead>
201	                        <tr>
202	                            <th>{ "Period Start" }</th>
203	                            <th>{ "Period End" }</th>
204	                            <th>{ "Value" }</th>
205	                        </tr>
206	                    </thead>
207	                    <tbody>
208	                        { for vals.iter().map(|v| html! {
209	                            <tr>
210	                                <td>{ v.period_start.format("%Y-%m-%d %H:%M").to_string() }</td>
211	                                <td>{ v.period_end.format("%Y-%m-%d %H:%M").to_string() }</td>
212	                                <td>{ format!("{:.4}", v.value) }</td>
213	                            </tr>
214	                        }) }
215	                    </tbody>
216	                </table>
217	            },
218	        };
219	
220	        let close_drill = {
221	            let dm = drilldown_metric.clone();
222	            Callback::from(move |_: MouseEvent| dm.set(None))
223	        };
224	
225	        html! {
226	            <div class="drilldown-panel">
227	                <div class="drilldown-panel__header">
228	                    <h2>{ format!("Drilldown: {}", metric.display_name) }</h2>
229	                    <button class="btn btn--secondary btn--small" onclick={close_drill}>
230	                        { "Close" }
231	                    </button>
232	                </div>
233	                <form onsubmit={fetch_drilldown} class="inline-form">
234	                    <label class="form-field form-field--inline">
235	                        <span>{ "From (date)" }</span>
236	                        <input type="date" class="form-field__input"
237	                               value={(*drill_from).clone()}
238	                               oninput={{
239	                                   let f = drill_from.clone();
240	                                   Callback::from(move |e: InputEvent| {
241	                                       let el: web_sys::HtmlInputElement = e.target_unchecked_into();
242	                                       f.set(el.value());
243	                                   })
244	                               }} />
245	                    </label>
246	                    <label class="form-field form-field--inline">
247	                        <span>{ "To (date)" }</span>
248	                        <input type="date" class="form-field__input"
249	                               value={(*drill_to).clone()}
250	                               oninput={{
251	                                   let t = drill_to.clone();
252	                                   Callback::from(move |e: InputEvent| {
253	                                       let el: web_sys::HtmlInputElement = e.target_unchecked_into();
254	                                       t.set(el.value());
255	                                   })
256	                               }} />
257	                    </label>
258	                    <button type="submit" class="btn btn--primary">{ "Fetch Values" }</button>
259	                </form>
260	                <div class="drilldown-panel__body">{ ds_body }</div>
261	            </div>
262	        }
263	    } else {
264	        html! {}
265	    };
266	
267	    // ── Action feedback ───────────────────────────────────────────────────────
268	
269	    let feedback = match &*action_state {
270	        ActionState::Working   => html! { <div class="action-feedback action-feedback--working">{ "Working…" }</div> },
271	        ActionState::Done(msg) => html! { <div class="action-feedback action-feedback--success">{ msg }</div> },
272	        ActionState::Failed(e) => html! { <div class="action-feedback action-feedback--error">{ e }</div> },
273	        _ => html! {},
274	    };
275	
276	    let reauth_overlay = if *action_state == ActionState::ReauthRequired {
277	        let pend = *pending_del;
278	        let ast  = action_state.clone();
279	        let del  = delete_metric.clone();
280	        html! {
281	            <ReauthPrompt
282	                on_success={Callback::from(move |_| {
283	                    if let Some(mid) = pend {
284	                        del.emit(mid);
285	                    } else {
286	                        ast.set(ActionState::Idle);
287	                    }
288	                })}
289	                on_cancel={Callback::from({
290	                    let ast = action_state.clone();
291	                    move |_| ast.set(ActionState::Idle)
292	                })}
293	            />
294	        }
295	    } else { html! {} };
296	
297	    html! {
298	        <div class="page">
299	            <header class="page__header">
300	                <h1 class="page__title">{ "KPI Metrics" }</h1>
301	            </header>
302	            <div class="page__body">
303	                <form onsubmit={create_metric} class="inline-form">
304	                    <label class="form-field form-field--inline">
305	                        <span>{ "Key" }</span>
306	                        <input type="text" placeholder="e.g. on_time_rate"
307	                               oninput={{
308	                                   let k = key_input.clone();
309	                                   Callback::from(move |e: InputEvent| {
310	                                       let el: web_sys::HtmlInputElement = e.target_unchecked_into();
311	                                       k.set(el.value());
312	                                   })
313	                               }}
314	                               class="form-field__input" />
315	                    </label>
316	                    <label class="form-field form-field--inline">
317	                        <span>{ "Display Name" }</span>
318	                        <input type="text" placeholder="On-Time Rate"
319	                               oninput={{
320	                                   let n = name_input.clone();
321	                                   Callback::from(move |e: InputEvent| {
322	                                       let el: web_sys::HtmlInputElement = e.target_unchecked_into();
323	                                       n.set(el.value());
324	                                   })
325	                               }}
326	                               class="form-field__input" />
327	                    </label>
328	                    <button type="submit" class="btn btn--primary">{ "Create Metric" }</button>
329	                </form>
330	                { feedback }
331	                { content }
332	                { drilldown_panel }
333	            </div>
334	            { reauth_overlay }
335	        </div>
336	    }
337	}
