1	/// Reporting: Report run history with export actions.
2	///
3	/// Lists all past report runs (both manual and scheduled), shows their status,
4	/// and provides export download links for completed runs in PDF or CSV format.
5	use wasm_bindgen_futures::spawn_local;
6	use yew::prelude::*;
7	
8	use crate::{
9	    services::reporting_service,
10	    types::reporting::ReportRun,
11	};
12	
13	#[derive(Clone, PartialEq)]
14	enum PageState { Loading, Loaded(Vec<ReportRun>), Error(String) }
15	
16	#[function_component(ReportRunsPage)]
17	pub fn report_runs_page() -> Html {
18	    let page_state = use_state(|| PageState::Loading);
19	
20	    {
21	        let ps = page_state.clone();
22	        use_effect_with((), move |_| {
23	            spawn_local(async move {
24	                match reporting_service::list_runs().await {
25	                    Ok(runs) => ps.set(PageState::Loaded(runs)),
26	                    Err(e)   => ps.set(PageState::Error(e)),
27	                }
28	            });
29	            || ()
30	        });
31	    }
32	
33	    let on_refresh = {
34	        let ps = page_state.clone();
35	        Callback::from(move |_: MouseEvent| {
36	            let ps = ps.clone();
37	            spawn_local(async move {
38	                ps.set(PageState::Loading);
39	                match reporting_service::list_runs().await {
40	                    Ok(runs) => ps.set(PageState::Loaded(runs)),
41	                    Err(e)   => ps.set(PageState::Error(e)),
42	                }
43	            });
44	        })
45	    };
46	
47	    let content = match &*page_state {
48	        PageState::Loading => html! {
49	            <div class="loading-state"><div class="spinner"/></div>
50	        },
51	        PageState::Error(e) => html! {
52	            <p class="error-state__message">{ e }</p>
53	        },
54	        PageState::Loaded(runs) if runs.is_empty() => html! {
55	            <div class="empty-state">
56	                <p>{ "No report runs yet." }</p>
57	                <p>{ "Trigger a run from the Report Schedules page." }</p>
58	            </div>
59	        },
60	        PageState::Loaded(runs) => {
61	            html! {
62	                <table class="data-table">
63	                    <thead>
64	                        <tr>
65	                            <th>{ "Started" }</th>
66	                            <th>{ "Status" }</th>
67	                            <th>{ "Format" }</th>
68	                            <th>{ "Period" }</th>
69	                            <th>{ "Completed" }</th>
70	                            <th>{ "Export" }</th>
71	                        </tr>
72	                    </thead>
73	                    <tbody>
74	                        { for runs.iter().map(|r| {
75	                            let run_id     = r.id;
76	                            let is_done    = r.is_completed();
77	                            let status_cls = if r.is_completed() { "badge--published" }
78	                                           else if r.is_running() { "badge--scheduled" }
79	                                           else { "badge--draft" };
80	                            let csv_url  = reporting_service::export_run_url(run_id, "csv");
81	                            let pdf_url  = reporting_service::export_run_url(run_id, "pdf");
82	                            // export_run_url is sync now — we use the String directly
83	                            html! {
84	                                <tr key={run_id.to_string()}>
85	                                    <td>{ r.started_at.format("%Y-%m-%d %H:%M").to_string() }</td>
86	                                    <td>
87	                                        <span class={format!("badge {}", status_cls)}>
88	                                            { &r.status }
89	                                        </span>
90	                                    </td>
91	                                    <td class="mono">{ &r.output_format }</td>
92	                                    <td>
93	                                        { format!(
94	                                            "{} – {}",
95	                                            r.date_from.format("%Y-%m-%d"),
96	                                            r.date_to.format("%Y-%m-%d"),
97	                                        ) }
98	                                    </td>
99	                                    <td>
100	                                        { r.completed_at
101	                                            .map(|t| t.format("%Y-%m-%d %H:%M").to_string())
102	                                            .unwrap_or_else(|| "—".to_string()) }
103	                                    </td>
104	                                    <td class="action-cell">
105	                                        if is_done {
106	                                            <a href={csv_url}
107	                                               download=""
108	                                               class="btn btn--small btn--secondary">
109	                                                { "CSV" }
110	                                            </a>
111	                                            { " " }
112	                                            <a href={pdf_url}
113	                                               download=""
114	                                               class="btn btn--small btn--secondary">
115	                                                { "PDF" }
116	                                            </a>
117	                                        }
118	                                    </td>
119	                                </tr>
120	                            }
121	                        }) }
122	                    </tbody>
123	                </table>
124	            }
125	        }
126	    };
127	
128	    html! {
129	        <div class="page">
130	            <header class="page__header">
131	                <h1 class="page__title">{ "Report Runs" }</h1>
132	                <div class="page__actions">
