22	#[function_component(FareRulesPage)]
23	pub fn fare_rules_page() -> Html {
24	    let page_state   = use_state(|| PageState::Loading);
25	    let form_state   = use_state(|| FormState::Hidden);
26	    let routes       = use_state::<Vec<OpsRoute>, _>(Vec::new);
27	    let del_working  = use_state(|| false);
