39	                match ops_service::list_fare_rules().await {
40	                    Ok(rules) => ps.set(PageState::Loaded(rules)),
41	                    Err(e)    => ps.set(PageState::Error(e)),
42	                }
43	            });
44	        }
45	    };
46	
47	    // Load fare rules and routes on mount
48	    {
49	        let rel = reload.clone();
50	        let rts = routes.clone();
51	        use_effect_with((), move |_| {
52	            rel();
53	            let rts = rts.clone();
