92	        })
93	    };
94	
95	    let on_delete = {
96	        let dw  = del_working.clone();
97	        let rel = reload.clone();
98	        Callback::from(move |rule_id: Uuid| {
99	            let dw2 = dw.clone();
100	            let rel = rel.clone();
