162	                                        </button>
163	                                    </td>
164	                                </tr>
165	                            }
166	                        }) }
167	                    </tbody>
168	                </table>
169	            }
170	        }
171	    };
172	
173	    // ── Create form modal ─────────────────────────────────────────────────────
174	
175	    let form_modal = match &*form_state {
176	        FormState::Visible | FormState::Submitting | FormState::Failed(_) => {
