199	                                            Callback::from(move |e: Event| {
200	                                                let el: web_sys::HtmlSelectElement = e.target_unchecked_into();
201	                                                t.set(el.value());
202	                                            })
203	                                        }}>
204	                                    { rule_type_options }
205	                                </select>
206	                            </label>
207	                            <label class="form-field">
