212	                                       oninput={{
213	                                           let f = fare_input.clone();
214	                                           Callback::from(move |e: InputEvent| {
215	                                               let el: web_sys::HtmlInputElement = e.target_unchecked_into();
216	                                               f.set(el.value());
217	                                           })
218	                                       }} />
219	                            </label>
220	                            <label class="form-field">
221	                                <span>{ "Route (optional)" }</span>
222	                                <select class="form-field__input"
223	                                        onchange={{
224	                                            let rs = route_sel.clone();
225	                                            Callback::from(move |e: Event| {
226	                                                let el: web_sys::HtmlSelectElement = e.target_unchecked_into();
227	                                                let val = el.value();
