241	                                    { "Cancel" }
242	                                </button>
243	                            </div>
244	                        </form>
245	                    </div>
246	                </div>
247	            }
248	        }
249	        FormState::Hidden => html! {}
250	    };
251	
252	    html! {
253	        <div class="page">
254	            <header class="page__header">
255	                <h1 class="page__title">{ "Fare Rules" }</h1>
256	                <div class="page__actions">
