5	/// An alert record.
6	#[derive(Clone, PartialEq, Deserialize, Debug)]
7	pub struct Alert {
8	    pub id:               Uuid,
9	    pub alert_type:       String,
10	    pub severity:         String,
11	    pub title:            String,
12	    pub description:      String,
13	    pub status:           String,
14	    pub source_entity_id: Option<Uuid>,
15	    pub acknowledged_by:  Option<Uuid>,
16	    pub acknowledged_at:  Option<DateTime<Utc>>,
17	    pub closed_by:        Option<Uuid>,
18	    pub closed_at:        Option<DateTime<Utc>>,
19	    pub created_at:       DateTime<Utc>,
20	}
21	
22	impl Alert {
23	    pub fn is_open(&self)         -> bool { self.status == "open" }
24	    pub fn is_acknowledged(&self) -> bool { self.status == "acknowledged" }
25	    pub fn is_closed(&self)       -> bool { self.status == "closed" }
26	
27	    pub fn severity_class(&self) -> &str {
28	        match self.severity.as_str() {
29	            "critical" => "alert--critical",
30	            "warning"  => "alert--warning",
31	            _          => "alert--info",
32	        }
33	    }
34	
35	    pub fn type_label(&self) -> &str {
36	        match self.alert_type.as_str() {
37	            "kpi_anomaly"        => "KPI Anomaly",
38	            "reconciliation"     => "Reconciliation",
39	            "system"             => "System",
40	            other                => other,
41	        }
42	    }
43	}
