45	/// Alert statistics.
46	#[derive(Clone, PartialEq, Deserialize, Debug, Default)]
47	pub struct AlertStats {
48	    pub total_open:         i64,
49	    pub total_critical:     i64,
50	    pub total_acknowledged: i64,
51	}
