53	// ── Alert rule subscription types ────────────────────────────────────────────
54	
55	/// An alert rule — defines conditions that, when matched, emit an alert.
56	///
57	/// `rule_type` controls which condition fields are meaningful:
58	///   - `"keyword"`          → conditions.keyword, conditions.match_mode
59	///   - `"topic"`            → conditions.topic
60	///   - `"entity_threshold"` → conditions.metric_key, conditions.threshold, conditions.operator
61	///   - `"spike_detection"`  → conditions.metric_key, conditions.multiplier, conditions.window_minutes
62	#[derive(Clone, PartialEq, Deserialize, Debug)]
63	pub struct AlertRule {
64	    pub id:                                Uuid,
65	    pub name:                              String,
66	    pub rule_type:                         String,
67	    pub severity:                          String,
68	    pub conditions:                        serde_json::Value,
69	    pub duplicate_suppression_window_secs: i32,
70	    pub is_active:                         bool,
71	    pub created_at:                        DateTime<Utc>,
72	    pub updated_at:                        DateTime<Utc>,
73	}
74	
75	impl AlertRule {
76	    pub fn rule_type_label(&self) -> &str {
77	        match self.rule_type.as_str() {
78	            "keyword"          => "Keyword",
79	            "topic"            => "Topic",
80	            "entity_threshold" => "Entity Threshold",
81	            "spike_detection"  => "Spike Detection",
82	            other              => other,
83	        }
84	    }
85	
86	    /// Returns a human-readable summary of the conditions for display in the table.
87	    pub fn conditions_summary(&self) -> String {
88	        match self.rule_type.as_str() {
89	            "keyword" => self.conditions.get("keyword")
90	                .and_then(|v| v.as_str())
91	                .map(|k| format!("keyword: {}", k))
92	                .unwrap_or_else(|| "—".to_string()),
93	            "topic" => self.conditions.get("topic")
94	                .and_then(|v| v.as_str())
95	                .map(|t| format!("topic: {}", t))
96	                .unwrap_or_else(|| "—".to_string()),
97	            "entity_threshold" => {
98	                let key = self.conditions.get("metric_key").and_then(|v| v.as_str()).unwrap_or("?");
99	                let thr = self.conditions.get("threshold").and_then(|v| v.as_f64()).unwrap_or(0.0);
100	                let op  = self.conditions.get("operator").and_then(|v| v.as_str()).unwrap_or("gt");
101	                format!("{} {} {:.2}", key, op, thr)
102	            }
103	            "spike_detection" => {
104	                let key = self.conditions.get("metric_key").and_then(|v| v.as_str()).unwrap_or("?");
105	                let mul = self.conditions.get("multiplier").and_then(|v| v.as_f64()).unwrap_or(2.0);
106	                format!("{} × {:.1}× spike", key, mul)
107	            }
108	            _ => "—".to_string(),
109	        }
110	    }
111	}
