932	    /// Exact copy of the inline encoder from `statements.rs`.
933	    /// Kept here to verify correctness independently of the DOM.
934	    fn to_base64(data: &[u8]) -> String {
935	        const TABLE: &[u8; 64] =
936	            b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
937	        let mut out = String::with_capacity((data.len() + 2) / 3 * 4);
938	        for chunk in data.chunks(3) {
939	            let n = (chunk[0] as u32) << 16
940	                | (if chunk.len() > 1 { chunk[1] as u32 } else { 0 }) << 8
941	                | (if chunk.len() > 2 { chunk[2] as u32 } else { 0 });
942	            out.push(TABLE[((n >> 18) & 63) as usize] as char);
943	            out.push(TABLE[((n >> 12) & 63) as usize] as char);
944	            out.push(if chunk.len() > 1 { TABLE[((n >> 6) & 63) as usize] as char } else { '=' });
945	            out.push(if chunk.len() > 2 { TABLE[(n & 63) as usize] as char } else { '=' });
946	        }
947	        out
948	    }
