1	/// Rollout manager page.
2	///
3	/// Allows an operations admin to load a rollout plan by template ID + plan ID,
4	/// then activate individual stages sequentially.  Stage activation is reauth-
5	/// gated; a 403 response reveals the ReauthPrompt, and after successful
6	/// re-authentication the stage activation is retried automatically.
7	///
8	/// States:
9	///   PageState:  Empty | Loading | Loaded(plan) | Error(message)
10	///   ActionState: Idle | Working | ReauthRequired | Done(msg) | Failed(msg)
11	use uuid::Uuid;
12	use wasm_bindgen_futures::spawn_local;
13	use yew::prelude::*;
14	
15	use crate::{
16	    components::reauth_prompt::ReauthPrompt,
17	    services::ops_service,
18	    types::ops::RolloutPlan,
19	};
20	
21	#[derive(Clone, PartialEq)]
22	enum PageState { Empty, Loading, Loaded(RolloutPlan), Error(String) }
23	
24	#[derive(Clone, PartialEq)]
25	enum ActionState {
26	    Idle,
27	    Working,
28	    ReauthRequired { stage_id: Uuid, plan_id: Uuid, template_id: Uuid },
29	    Done(String),
30	    Failed(String),
31	}
32	
33	#[function_component(RolloutManagerPage)]
34	pub fn rollout_manager_page() -> Html {
35	    // In production these IDs come from route params or a preceding config-list
36	    // navigation; here we expose text inputs so any authenticated admin can
37	    // load any plan without requiring deep-link URL construction.
38	    let template_input = use_state(String::new);
39	    let plan_input     = use_state(String::new);
40	    let page_state     = use_state(|| PageState::Empty);
41	    let action_state   = use_state(|| ActionState::Idle);
42	
43	    // ── Load plan ─────────────────────────────────────────────────────────────
44	
