50	            e.prevent_default();
51	
52	            let tid = match (*ti).parse::<Uuid>() {
53	                Ok(id) => id,
54	                Err(_) => {
55	                    ps.set(PageState::Error("Template ID must be a valid UUID.".to_string()));
56	                    return;
57	                }
58	            };
59	            let pid = match (*pi).parse::<Uuid>() {
60	                Ok(id) => id,
61	                Err(_) => {
62	                    ps.set(PageState::Error("Plan ID must be a valid UUID.".to_string()));
63	                    return;
64	                }
65	            };
66	
67	            let ps2 = ps.clone();
68	            ps.set(PageState::Loading);
69	            spawn_local(async move {
70	                match ops_service::get_rollout_plan(tid, pid).await {
71	                    Ok(plan)  => ps2.set(PageState::Loaded(plan)),
72	                    Err(e)    => ps2.set(PageState::Error(e)),
73	                }
74	            });
75	        })
