77	
78	    // ── Activate a stage ──────────────────────────────────────────────────────
79	
80	    let activate_stage = {
81	        let action_state = action_state.clone();
82	        let ti           = template_input.clone();
83	        let pi           = plan_input.clone();
84	        let ps           = page_state.clone();
85	        Callback::from(move |stage_id: Uuid| {
86	            let tid = match (*ti).parse::<Uuid>() {
87	                Ok(id) => id,
88	                Err(_) => return,
89	            };
90	            let pid = match (*pi).parse::<Uuid>() {
91	                Ok(id) => id,
92	                Err(_) => return,
93	            };
94	            let ast = action_state.clone();
95	            let ps2 = ps.clone();
96	            let ti2 = tid;
97	            let pi2 = pid;
98	            spawn_local(async move {
99	                ast.set(ActionState::Working);
100	                match ops_service::activate_stage(ti2, pi2, stage_id).await {
101	                    Ok(_) => {
102	                        ast.set(ActionState::Done("Stage activated successfully.".to_string()));
103	                        // Reload plan to reflect updated stage statuses
104	                        match ops_service::get_rollout_plan(ti2, pi2).await {
105	                            Ok(plan) => ps2.set(PageState::Loaded(plan)),
106	                            Err(e)   => ps2.set(PageState::Error(e)),
107	                        }
108	                    }
109	                    Err(e) => {
110	                        if e.contains("[403]") {
111	                            ast.set(ActionState::ReauthRequired {
112	                                stage_id, plan_id: pi2, template_id: ti2,
113	                            });
114	                        } else {
115	                            ast.set(ActionState::Failed(e));
116	                        }
117	                    }
118	                }
119	            });
120	        })
121	    };
122	
123	    // ── Reauth overlay ────────────────────────────────────────────────────────
124	
125	    let reauth_overlay = if let ActionState::ReauthRequired { stage_id, .. } = &*action_state {
126	        let sid = *stage_id;
127	        let ast = action_state.clone();
128	        let act = activate_stage.clone();
129	        html! {
130	            <ReauthPrompt
131	                on_success={Callback::from(move |_| act.emit(sid))}
132	                on_cancel={Callback::from(move |_| ast.set(ActionState::Idle))}
133	            />
134	        }
135	    } else { html! {} };
136	
137	    // ── Body ──────────────────────────────────────────────────────────────────
138	
139	    let is_loading = matches!(*page_state, PageState::Loading);
140	
141	    let body = match &*page_state {
142	        PageState::Empty => html! {
143	            <div class="empty-state">
144	                <p>{ "Enter a template ID and plan ID above to load a rollout plan." }</p>
145	                <p class="hint">
146	                    { "Rollout plans are created from a published config version. \
147	                       A plan progresses through stages: 10% → 50% → 100% of depots." }
148	                </p>
149	            </div>
150	        },
151	        PageState::Loading => html! { <div class="spinner" /> },
152	        PageState::Error(e) => html! {
153	            <div class="error-state">
154	                <p class="error-state__message">{ e }</p>
155	                <button class="btn btn--secondary"
156	                        onclick={{
157	                            let ps = page_state.clone();
158	                            Callback::from(move |_| ps.set(PageState::Empty))
159	                        }}>
160	                    { "Try again" }
161	                </button>
162	            </div>
163	        },
164	        PageState::Loaded(plan) => {
165	            let act_cb        = activate_stage.clone();
166	            let is_working    = matches!(*action_state, ActionState::Working);
167	            html! {
168	                <div class="rollout-plan">
