0	/// Frontend component integration tests.
1	///
2	/// Tests cover real production code paths rather than synthetic local enums:
3	///   - Auth/role-guard routing decisions using the real `SessionInfo` type
4	///   - Token key consistency (auth_store TOKEN_KEY used by all services)
5	///   - Login/logout action and route-guard state changes
6	///   - Rollout page state transitions: load, error, reauth-required action
7	///   - Statement import validation logic (extension, empty, no-selection)
8	///   - DND hour validation (0–23 clamping, input binding)
9	///   - Scheduled publish form (datetime parsing, request serialisation)
10	///   - Reporting export URL generation and drilldown state
11	///   - Ops admin page state machine (route/stop/calendar/fare rule CRUD)
12	///   - Base64 encoder correctness (used in the file upload path)
13	///
14	/// Run with:
15	///   wasm-pack test --headless --firefox -- --test component_states
16	use wasm_bindgen_test::*;
17	
18	wasm_bindgen_test_configure!(run_in_browser);
19	
20	// ── Real type imports ─────────────────────────────────────────────────────────
21	
22	use transitops_frontend::types::alerting::{AlertRule, CreateAlertRuleRequest};
23	use transitops_frontend::types::auth::SessionInfo;
24	use transitops_frontend::types::ops::{
25	    ChangePolicy, CreateChangePolicyRequest, CreateFareRuleRequest,
26	    CreateOpsRouteRequest, CreateOpsStopRequest, CreateRefundPolicyRequest,
27	    FareRule, OpsCalendar, OpsRoute, OpsStop, RefundPolicy, RolloutPlan, RolloutStage,
28	};
29	use transitops_frontend::types::reporting::{MetricValue, ReportRun};
30	
31	// ── Auth / role-guard routing using real SessionInfo ─────────────────────────
32	
33	mod auth_role_guard {
34	    use super::*;
35	
36	    fn make_session(role: &str) -> SessionInfo {
37	        SessionInfo {
38	            username:   "testuser".to_string(),
39	            role:       role.to_string(),
40	            session_id: None,
41	        }
42	    }
43	
44	    #[wasm_bindgen_test]
45	    fn unauthenticated_should_redirect() {
46	        // No session ⇒ AuthGuard redirects to /login
47	        let session: Option<SessionInfo> = None;
48	        let redirect = session.is_none();
49	        assert!(redirect, "No session must redirect to /login");
50	    }
51	
52	    #[wasm_bindgen_test]
53	    fn authenticated_passes_auth_guard() {
54	        let session = Some(make_session("staff_user"));
55	        let redirect = session.is_none();
56	        assert!(!redirect, "Authenticated user should not be redirected");
57	    }
58	
59	    #[wasm_bindgen_test]
60	    fn admin_can_access_rollout_page() {
61	        let s = make_session("operations_admin");
62	        assert!(s.is_admin(), "operations_admin must pass RoleGuard for rollout");
63	    }
64	
65	    #[wasm_bindgen_test]
66	    fn dispatcher_cannot_access_rollout_page() {
67	        let s = make_session("dispatcher");
68	        assert!(!s.is_admin(), "dispatcher must be blocked from rollout (admin-only)");
69	    }
70	
71	    #[wasm_bindgen_test]
72	    fn dispatcher_can_access_config_list() {
73	        let s = make_session("dispatcher");
74	        let allowed = s.is_admin() || s.is_dispatcher();
75	        assert!(allowed, "dispatcher must access config list");
76	    }
77	
78	    #[wasm_bindgen_test]
79	    fn finance_analyst_can_access_statements() {
80	        let s = make_session("finance_analyst");
81	        let allowed = s.is_finance() || s.is_admin();
82	        assert!(allowed, "finance_analyst must access statements page");
83	    }
84	
