930	
931	mod base64_encoding {
932	    use super::*;
933	
934	    /// Exact copy of the inline encoder from `statements.rs`.
935	    /// Kept here to verify correctness independently of the DOM.
936	    fn to_base64(data: &[u8]) -> String {
937	        const TABLE: &[u8; 64] =
938	            b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
939	        let mut out = String::with_capacity((data.len() + 2) / 3 * 4);
940	        for chunk in data.chunks(3) {
941	            let n = (chunk[0] as u32) << 16
942	                | (if chunk.len() > 1 { chunk[1] as u32 } else { 0 }) << 8
943	                | (if chunk.len() > 2 { chunk[2] as u32 } else { 0 });
944	            out.push(TABLE[((n >> 18) & 63) as usize] as char);
945	            out.push(TABLE[((n >> 12) & 63) as usize] as char);
946	            out.push(if chunk.len() > 1 { TABLE[((n >> 6) & 63) as usize] as char } else { '=' });
947	            out.push(if chunk.len() > 2 { TABLE[(n & 63) as usize] as char } else { '=' });
948	        }
949	        out
950	    }
951	
952	    #[wasm_bindgen_test]
953	    fn encodes_empty_input_to_empty_string() {
954	        assert_eq!(to_base64(b""), "");
955	    }
956	
957	    #[wasm_bindgen_test]
958	    fn encodes_single_byte_m() {
959	        // "M" → "TQ=="  (RFC 4648 known vector)
960	        assert_eq!(to_base64(b"M"), "TQ==");
961	    }
962	
963	    #[wasm_bindgen_test]
964	    fn encodes_two_bytes_ma() {
965	        // "Ma" → "TWE="
966	        assert_eq!(to_base64(b"Ma"), "TWE=");
967	    }
968	
969	    #[wasm_bindgen_test]
970	    fn encodes_three_bytes_man() {
971	        // "Man" → "TWFu"
972	        assert_eq!(to_base64(b"Man"), "TWFu");
973	    }
974	
975	    #[wasm_bindgen_test]
976	    fn encodes_hello_world() {
977	        // Known-good vector
978	        assert_eq!(to_base64(b"Hello, World!"), "SGVsbG8sIFdvcmxkIQ==");
979	    }
