    fn parse_depot_ids(raw: &str) -> Result<Vec<Uuid>, String> {
        let parts: Vec<&str> = raw
            .split(',')
            .map(|s| s.trim())
            .filter(|s| !s.is_empty())
            .collect();
        if parts.is_empty() {
            return Err("At least one depot UUID is required".to_string());
