        let raw = format!("{},{},{}", id1, id2, id3);
        let ids = parse_depot_ids(&raw).expect("three valid UUIDs must parse");
        assert_eq!(ids.len(), 3);
        assert!(ids.contains(&id1) && ids.contains(&id2) && ids.contains(&id3));
    }

    #[wasm_bindgen_test]
